def name_initials(self: object, name: str) -> str:
    words = re.findall(r"[^\W\d_]+", name)
    letters = [word[0] for word in words]
    initials = "".join(letters)
    return initials.upper()

def make_slug(self: object, text: str, separator: str = "-", max_length: int = 80) -> str:
    if separator not in ("-", "_"):
        raise ValueError("Slug separator must be '-' or '_'")
    if max_length < 1:
        raise ValueError("Maximum slug length must be positive")
    decomposed = unicodedata.normalize("NFKD", text)
    ascii_text = decomposed.encode("ascii", "ignore").decode("ascii")
    words = re.findall(r"[a-z0-9]+", ascii_text.lower())
    slug = separator.join(words)
    if len(slug) <= max_length:
        return slug
    shortened = slug[:max_length]
    if slug[max_length] != separator:
        boundary = shortened.rfind(separator)
        if boundary > 0:
            shortened = shortened[:boundary]
    return shortened.rstrip(separator)

def parse_text_properties(self: object, text: str, delimiter: str = ";") -> dict[str, str]:
    if not delimiter:
        raise ValueError("Property delimiter must not be empty")
    properties: dict[str, str] = {}
    for position, segment in enumerate(text.split(delimiter), start=1):
        segment = segment.strip()
        if not segment:
            continue
        key, marker, value = segment.partition("=")
        if not marker:
            raise ValueError(f"Property {position} has no equals sign")
        key = key.strip()
        if not key:
            raise ValueError(f"Property {position} has an empty key")
        if key in properties:
            raise ValueError(f"Duplicate property key: {key}")
        properties[key] = value.strip()
    return properties

def render_named_template(self: object, template: str, values: dict[str, object], *, strict: bool = True) -> str:
    pieces: list[str] = []
    cursor = 0
    pattern = r"\{\{|\}\}|\{([A-Za-z_][A-Za-z0-9_]*)\}|[{}]"
    for match in re.finditer(pattern, template):
        pieces.append(template[cursor:match.start()])
        token = match.group(0)
        name = match.group(1)
        if token == "{{":
            pieces.append("{")
        elif token == "}}":
            pieces.append("}")
        elif name is not None:
            if name in values:
                value = values[name]
                pieces.append("" if value is None else str(value))
            elif strict:
                raise KeyError(f"Missing template value: {name}")
            else:
                pieces.append(token)
        elif strict:
            raise ValueError(f"Invalid template brace at position {match.start()}")
        else:
            pieces.append(token)
        cursor = match.end()
    pieces.append(template[cursor:])
    return "".join(pieces)

def tokenize_search_query(self: object, query: str, *, fold_case: bool = False) -> list[str]:
    tokens: list[str] = []
    buffer: list[str] = []
    quote: str | None = None
    escaped = False
    started = False
    for character in query:
        if escaped:
            buffer.append(character)
            escaped = False
        elif character == "\\" and quote != "'":
            escaped = True
            started = True
        elif quote is not None:
            if character == quote:
                quote = None
            else:
                buffer.append(character)
        elif character in ("'", '"'):
            quote = character
            started = True
        elif character.isspace():
            if started:
                token = "".join(buffer)
                tokens.append(token.casefold() if fold_case else token)
                buffer.clear()
                started = False
        else:
            buffer.append(character)
            started = True
    if escaped:
        raise ValueError("Search query ends with an unfinished escape")
    if quote is not None:
        raise ValueError(f"Search query has an unclosed {quote} quote")
    if started:
        token = "".join(buffer)
        tokens.append(token.casefold() if fold_case else token)
    return tokens

def iter_nonblank_lines(text: str) -> Iterator[str]:
    for line in text.splitlines():
        cleaned = line.strip()
        if not cleaned:
            continue
        yield cleaned

def iter_word_spans(text: str) -> Iterator[tuple[str, int, int]]:
    for match in re.finditer(r"[^\W_]+(?:['’][^\W_]+)*", text):
        word = match.group(0)
        start = match.start()
        end = match.end()
        yield word, start, end

def iter_setting_pairs(text: str, separator: str = "=", comment_prefix: str = "#") -> Iterator[tuple[str, str]]:
    if not separator:
        raise ValueError("The setting separator must not be empty")
    for number, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped or (comment_prefix and stripped.startswith(comment_prefix)):
            continue
        key, marker, value = stripped.partition(separator)
        if not marker:
            raise ValueError(f"Missing setting separator on line {number}")
        key = key.strip()
        if not key:
            raise ValueError(f"Empty setting name on line {number}")
        yield key, value.strip()

def iter_text_matches(text: str, needle: str, overlap: bool = False, whole_word: bool = False) -> Iterator[int]:
    if not needle:
        raise ValueError("The search string must not be empty")
    position = 0
    while position <= len(text) - len(needle):
        found = text.find(needle, position)
        if found < 0:
            break
        end = found + len(needle)
        left_boundary = found == 0 or not (text[found - 1].isalnum() or text[found - 1] == "_")
        right_boundary = end == len(text) or not (text[end].isalnum() or text[end] == "_")
        accepted = not whole_word or (left_boundary and right_boundary)
        if accepted:
            yield found
        position = found + (len(needle) if accepted and not overlap else 1)

def iter_template_tokens(template: str, *, strict: bool = True) -> Iterator[tuple[str, str]]:
    position = 0
    literal = []
    while position < len(template):
        if template.startswith("$$", position):
            literal.append("$")
            position += 2
            continue
        if not template.startswith("${", position):
            literal.append(template[position])
            position += 1
            continue
        closing = template.find("}", position + 2)
        if closing < 0:
            if strict:
                raise ValueError(f"Unclosed template field at offset {position}")
            literal.append(template[position:])
            break
        name = template[position + 2:closing]
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*", name):
            if strict:
                raise ValueError(f"Invalid template field at offset {position}: {name!r}")
            literal.append(template[position:closing + 1])
            position = closing + 1
            continue
        if literal:
            yield "text", "".join(literal)
            literal.clear()
        yield "field", name
        position = closing + 1
    if literal:
        yield "text", "".join(literal)

async def parse_delimited_text(text: str, delimiter: str = ",", strip_fields: bool = True, skip_empty_rows: bool = True) -> list[list[str]]:
    if len(delimiter) != 1 or delimiter in {"\r", "\n", '"'}:
        raise ValueError("Delimiter must be one character other than a newline or quote")
    await asyncio.sleep(0)
    rows: list[list[str]] = []
    stream = io.StringIO(text, newline="")
    reader = csv.reader(stream, delimiter=delimiter, strict=True)
    try:
        for row in reader:
            if skip_empty_rows and not row:
                continue
            if strip_fields:
                row = [field.strip() for field in row]
            rows.append(row)
    except csv.Error as error:
        raise ValueError(f"Invalid delimited text near line {reader.line_num}: {error}") from error
    finally:
        stream.close()
    return rows

async def find_text_excerpts(text: str, query: str, context: int = 25, max_hits: int = 10) -> list[tuple[int, str]]:
    if context < 0:
        raise ValueError("Context length cannot be negative")
    if max_hits < 0:
        raise ValueError("Maximum hits cannot be negative")
    await asyncio.sleep(0)
    if not query or max_hits == 0:
        return []
    pattern = re.compile(re.escape(query), re.IGNORECASE)
    results: list[tuple[int, str]] = []
    for match in pattern.finditer(text):
        start = max(0, match.start() - context)
        end = min(len(text), match.end() + context)
        excerpt = text[start:end]
        if start > 0:
            excerpt = "…" + excerpt
        if end < len(text):
            excerpt += "…"
        results.append((match.start(), excerpt))
        if len(results) == max_hits:
            break
    return results

async def render_remote_template(template: str, client: Any, *, timeout: float = 5.0, missing_value: str | None = None) -> str:
    if not math.isfinite(timeout) or timeout <= 0:
        raise ValueError("Timeout must be finite and positive")
    pattern = re.compile(r"\{\{\s*([A-Za-z_][A-Za-z0-9_.]*)\s*\}\}")
    matches = list(pattern.finditer(template))
    if not matches:
        await asyncio.sleep(0)
        return template
    values: dict[str, str] = {}
    for match in matches:
        key = match.group(1)
        if key in values:
            continue
        try:
            value = await asyncio.wait_for(client.fetch_text(key), timeout=timeout)
        except KeyError:
            if missing_value is None:
                raise KeyError(f"No template value exists for {key!r}") from None
            value = missing_value
        except TimeoutError as error:
            raise TimeoutError(f"Fetching template value {key!r} timed out") from error
        if not isinstance(value, str):
            raise TypeError(f"Template value {key!r} must be a string")
        values[key] = value
    parts: list[str] = []
    cursor = 0
    for match in matches:
        parts.append(template[cursor:match.start()])
        parts.append(values[match.group(1)])
        cursor = match.end()
    parts.append(template[cursor:])
    return "".join(parts)

async def parse_assignment_text(text: str, *, duplicate_policy: str = "error", lowercase_keys: bool = False, allow_empty_values: bool = True) -> dict[str, str]:
    if duplicate_policy not in {"error", "first", "last"}:
        raise ValueError("Duplicate policy must be error, first, or last")
    await asyncio.sleep(0)
    try:
        tokens = shlex.split(text, comments=False, posix=True)
    except ValueError as error:
        raise ValueError(f"Invalid quoting in assignment text: {error}") from error
    assignments: dict[str, str] = {}
    for position, token in enumerate(tokens, start=1):
        if "=" not in token:
            raise ValueError(f"Assignment {position} is missing an equals sign")
        key, value = token.split("=", 1)
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_.-]*", key):
            raise ValueError(f"Assignment {position} has an invalid key: {key!r}")
        if lowercase_keys:
            key = key.lower()
        if not value and not allow_empty_values:
            raise ValueError(f"Assignment {key!r} has an empty value")
        if key in assignments:
            if duplicate_policy == "error":
                raise ValueError(f"Duplicate assignment for {key!r}")
            if duplicate_policy == "first":
                continue
        assignments[key] = value
    return assignments

def discounted_price(price: float, discount_percent: float) -> float:
    if not math.isfinite(price) or price < 0:
        raise ValueError("Price must be finite and nonnegative")
    if not math.isfinite(discount_percent) or not 0 <= discount_percent <= 100:
        raise ValueError("Discount percentage must be between zero and one hundred")
    discounted = price * (1 - discount_percent / 100)
    return round(discounted, 2)

def period_returns(prices: list[float]) -> list[float]:
    if any(not math.isfinite(price) or price <= 0 for price in prices):
        raise ValueError("Prices must be finite and strictly positive")
    returns = []
    for index in range(1, len(prices)):
        previous = prices[index - 1]
        current = prices[index]
        returns.append(current / previous - 1)
    return returns

def monthly_loan_payment(principal: float, annual_rate: float, months: int, financed_fee: float = 0.0) -> float:
    amounts = (principal, annual_rate, financed_fee)
    if any(not math.isfinite(value) or value < 0 for value in amounts):
        raise ValueError("Principal, annual rate, and financed fee must be finite and nonnegative")
    if isinstance(months, bool) or not isinstance(months, int):
        raise TypeError("Loan term must be an integer number of months")
    if months <= 0:
        raise ValueError("Loan term must be positive")
    balance = principal + financed_fee
    if not math.isfinite(balance):
        raise ValueError("Financed balance is too large")
    if annual_rate == 0:
        return balance / months
    monthly_rate = annual_rate / 12
    denominator = -math.expm1(-months * math.log1p(monthly_rate))
    if denominator == 0:
        return balance / months
    return balance * (monthly_rate / denominator)

def invoice_totals(items: list[tuple[Decimal, int]], tax_rate: Decimal = Decimal("0"), discount_rate: Decimal = Decimal("0")) -> dict[str, Decimal]:
    if not tax_rate.is_finite() or tax_rate < 0:
        raise ValueError("Tax rate must be finite and nonnegative")
    if not discount_rate.is_finite() or not Decimal("0") <= discount_rate <= Decimal("1"):
        raise ValueError("Discount rate must be between zero and one")
    cent = Decimal("0.01")
    subtotal = Decimal("0")
    for unit_price, quantity in items:
        if not unit_price.is_finite() or unit_price < 0:
            raise ValueError("Unit prices must be finite and nonnegative")
        if isinstance(quantity, bool) or not isinstance(quantity, int):
            raise TypeError("Item quantities must be integers")
        if quantity < 0:
            raise ValueError("Item quantities must be nonnegative")
        subtotal += (unit_price * quantity).quantize(cent, rounding="ROUND_HALF_UP")
    subtotal = subtotal.quantize(cent, rounding="ROUND_HALF_UP")
    discount = (subtotal * discount_rate).quantize(cent, rounding="ROUND_HALF_UP")
    taxable_amount = subtotal - discount
    tax = (taxable_amount * tax_rate).quantize(cent, rounding="ROUND_HALF_UP")
    total = taxable_amount + tax
    return {"subtotal": subtotal, "discount": discount, "tax": tax, "total": total}

def rebalance_portfolio(holdings: dict[str, float], prices: dict[str, float], target_weights: dict[str, float], *, cash: float = 0.0, fractional_shares: bool = False) -> tuple[dict[str, float], float]:
    if not math.isfinite(cash) or cash < 0:
        raise ValueError("Cash must be finite and nonnegative")
    if not target_weights:
        raise ValueError("At least one target allocation is required")
    if any(not math.isfinite(weight) or weight < 0 for weight in target_weights.values()):
        raise ValueError("Target weights must be finite and nonnegative")
    weight_sum = sum(target_weights.values())
    if not math.isclose(weight_sum, 1.0, rel_tol=0.0, abs_tol=1e-9):
        raise ValueError("Target weights must sum to one")
    symbols = sorted(set(holdings) | set(target_weights))
    equity = cash
    for symbol in symbols:
        if symbol not in prices:
            raise KeyError(f"Missing price for {symbol}")
        price = prices[symbol]
        shares = holdings.get(symbol, 0.0)
        if not math.isfinite(price) or price <= 0:
            raise ValueError(f"Price for {symbol} must be finite and positive")
        if not math.isfinite(shares) or shares < 0:
            raise ValueError(f"Holdings for {symbol} must be finite and nonnegative")
        equity += shares * price
    if not math.isfinite(equity):
        raise ValueError("Portfolio equity is too large")
    trades = {}
    invested = 0.0
    for symbol in symbols:
        allocation = equity * (target_weights.get(symbol, 0.0) / weight_sum)
        desired = allocation / prices[symbol]
        if not math.isfinite(desired):
            raise ValueError(f"Target share count for {symbol} is too large")
        if not fractional_shares:
            desired = math.floor(desired)
        trades[symbol] = desired - holdings.get(symbol, 0.0)
        invested += desired * prices[symbol]
    return trades, max(0.0, equity - invested)

def convert_currency(amount: float, quotes: dict[tuple[str, str], tuple[float, float]], *, source: str, target: str, bridge: str = "USD", fee_rate: float = 0.0) -> float:
    if not math.isfinite(amount) or amount < 0:
        raise ValueError("Amount must be finite and nonnegative")
    if not math.isfinite(fee_rate) or not 0 <= fee_rate < 1:
        raise ValueError("Fee rate must be between zero inclusive and one exclusive")
    source = source.strip().upper()
    target = target.strip().upper()
    bridge = bridge.strip().upper()
    if not source or not target or not bridge:
        raise ValueError("Currency codes must not be empty")
    if source == target:
        return amount
    if (source, target) in quotes or (target, source) in quotes:
        route = [(source, target)]
    elif source == bridge or target == bridge:
        raise KeyError(f"No quote available for {source}/{target}")
    else:
        route = [(source, bridge), (bridge, target)]
    converted = amount
    for base, counter in route:
        direct = (base, counter) in quotes
        key = (base, counter) if direct else (counter, base)
        if key not in quotes:
            raise KeyError(f"No quote available for {base}/{counter}")
        bid, ask = quotes[key]
        if not math.isfinite(bid) or not math.isfinite(ask) or not 0 < bid <= ask:
            raise ValueError(f"Invalid bid and ask for {key[0]}/{key[1]}")
        if direct:
            converted *= bid
        else:
            converted /= ask
        if not math.isfinite(converted):
            raise ValueError("Converted amount is too large")
    return converted * (1 - fee_rate)

async def apply_savings_interest(balance: float, period_rate: float) -> float:
    if not math.isfinite(balance) or balance < 0:
        raise ValueError("Balance must be finite and nonnegative")
    if not math.isfinite(period_rate) or period_rate < -1:
        raise ValueError("Period rate must be finite and at least -1")
    await asyncio.sleep(0)
    return balance * (1 + period_rate)

async def calculate_weighted_portfolio_return(client: object, weights: dict[str, float], days: int = 30) -> float:
    if days <= 0:
        raise ValueError("The holding period must be positive")
    holdings = list(weights.items())
    if not holdings:
        raise ValueError("At least one portfolio holding is required")
    if any(not math.isfinite(weight) or weight < 0 for _, weight in holdings):
        raise ValueError("Portfolio weights must be finite and nonnegative")
    weight_total = math.fsum(weight for _, weight in holdings)
    if weight_total <= 0:
        raise ValueError("Portfolio weights must have a positive total")
    requests = [client.get_period_return(symbol, days) for symbol, _ in holdings]
    responses = await asyncio.gather(*requests)
    returns = [float(response) for response in responses]
    if any(not math.isfinite(value) or value < -1 for value in returns):
        raise ValueError("Holding returns must be finite and at least -1")
    contributions = [(weight / weight_total) * value for (_, weight), value in zip(holdings, returns)]
    return math.fsum(contributions)

async def convert_currency_amount(client: object, amount: Decimal, source: str, target: str, *, fee_rate: Decimal = Decimal("0"), minor_units: int = 2) -> Decimal:
    source_code = source.strip().upper()
    target_code = target.strip().upper()
    if not re.fullmatch(r"[A-Z]{3}", source_code):
        raise ValueError("Source currency must be a three-letter code")
    if not re.fullmatch(r"[A-Z]{3}", target_code):
        raise ValueError("Target currency must be a three-letter code")
    if not amount.is_finite() or amount < 0:
        raise ValueError("Conversion amount must be finite and nonnegative")
    if not fee_rate.is_finite() or not Decimal("0") <= fee_rate < Decimal("1"):
        raise ValueError("Fee rate must be finite and between zero and one, excluding one")
    if not 0 <= minor_units <= 6:
        raise ValueError("Minor units must be between zero and six")
    if source_code == target_code:
        await asyncio.sleep(0)
        rate = Decimal("1")
    else:
        response = await client.get_fx_rate(source_code, target_code)
        rate = Decimal(str(response))
        if not rate.is_finite() or rate <= 0:
            raise ValueError("Exchange rate must be finite and positive")
    gross_amount = amount * rate
    if fee_rate:
        net_amount = gross_amount * (Decimal("1") - fee_rate)
    else:
        net_amount = gross_amount
    quantum = Decimal("1").scaleb(-minor_units)
    return net_amount.quantize(quantum, rounding=ROUND_HALF_UP)

async def build_monthly_loan_schedule(principal: float, annual_rate: float, *, payments: int, monthly_extra: float = 0.0) -> list[dict[str, float | int]]:
    if not math.isfinite(principal) or principal <= 0:
        raise ValueError("Principal must be finite and positive")
    if not math.isfinite(annual_rate) or annual_rate < 0:
        raise ValueError("Annual rate must be finite and nonnegative")
    if payments <= 0:
        raise ValueError("Payment count must be positive")
    if not math.isfinite(monthly_extra) or monthly_extra < 0:
        raise ValueError("Extra payment must be finite and nonnegative")
    monthly_rate = annual_rate / 12
    if monthly_rate == 0:
        scheduled_payment = principal / payments
    else:
        denominator = -math.expm1(-payments * math.log1p(monthly_rate))
        scheduled_payment = principal * (monthly_rate / denominator)
    budget = scheduled_payment + monthly_extra
    if not math.isfinite(budget):
        raise ValueError("Calculated payment exceeds the supported numeric range")
    balance = principal
    schedule = []
    for month in range(1, payments + 1):
        if month == 1 or month % 100 == 0:
            await asyncio.sleep(0)
        interest = balance * monthly_rate
        amount_due = balance + interest
        if not math.isfinite(amount_due):
            raise ValueError("Loan balance exceeds the supported numeric range")
        if month == payments:
            payment = amount_due
        else:
            payment = min(budget, amount_due)
        principal_paid = payment - interest
        balance = max(0.0, balance - principal_paid)
        schedule.append({"month": month, "payment": payment, "interest": interest, "principal": principal_paid, "balance": balance})
        if balance == 0:
            break
    return schedule

def holding_weight(self: "Portfolio", symbol: str) -> Decimal:
    holding_value = self.market_values.get(symbol, Decimal("0"))
    total_value = sum(self.market_values.values(), Decimal("0"))
    if total_value == 0:
        return Decimal("0")
    weight = holding_value / total_value
    return weight

def quote_currency_conversion(self: "CurrencyDesk", amount: Decimal, source: str, target: str, fee_rate: Decimal = Decimal("0")) -> Decimal:
    if not amount.is_finite() or amount < 0:
        raise ValueError("Conversion amount must be finite and nonnegative")
    if not fee_rate.is_finite() or not Decimal("0") <= fee_rate < Decimal("1"):
        raise ValueError("Fee rate must be between zero inclusive and one exclusive")
    if source not in self.units_per_base:
        raise KeyError(f"No exchange rate for source currency {source}")
    if target not in self.units_per_base:
        raise KeyError(f"No exchange rate for target currency {target}")
    source_rate = self.units_per_base[source]
    target_rate = self.units_per_base[target]
    if not source_rate.is_finite() or source_rate <= 0:
        raise ValueError("Source exchange rate must be finite and positive")
    if not target_rate.is_finite() or target_rate <= 0:
        raise ValueError("Target exchange rate must be finite and positive")
    if target not in self.currency_quantums:
        raise KeyError(f"No rounding quantum for currency {target}")
    gross = amount / source_rate * target_rate
    net = gross * (Decimal("1") - fee_rate)
    return net.quantize(self.currency_quantums[target], rounding=ROUND_HALF_UP)

def propose_rebalance_trades(self: "Portfolio", target_weights: dict[str, Decimal], *, cash: Decimal = Decimal("0"), minimum_trade: Decimal = Decimal("0")) -> dict[str, Decimal]:
    if not cash.is_finite() or cash < 0:
        raise ValueError("Available cash must be finite and nonnegative")
    if not minimum_trade.is_finite() or minimum_trade < 0:
        raise ValueError("Minimum trade must be finite and nonnegative")
    total_weight = Decimal("0")
    for symbol, weight in target_weights.items():
        if not weight.is_finite() or not Decimal("0") <= weight <= Decimal("1"):
            raise ValueError(f"Invalid target weight for {symbol}")
        total_weight += weight
    if total_weight > Decimal("1"):
        raise ValueError("Target weights must not sum to more than one")
    symbols = sorted(set(self.positions) | set(target_weights))
    current_values = {}
    capital = cash
    for symbol in symbols:
        if symbol not in self.prices:
            raise KeyError(f"Missing market price for {symbol}")
        price = self.prices[symbol]
        quantity = self.positions.get(symbol, Decimal("0"))
        if not price.is_finite() or price <= 0:
            raise ValueError(f"Market price must be finite and positive for {symbol}")
        if not quantity.is_finite() or quantity < 0:
            raise ValueError(f"Position must be finite and nonnegative for {symbol}")
        value = quantity * price
        current_values[symbol] = value
        capital += value
    if capital == 0:
        return {}
    trades = {}
    for symbol in symbols:
        target_value = capital * target_weights.get(symbol, Decimal("0"))
        difference = target_value - current_values[symbol]
        rounded = difference.quantize(self.currency_quantum, rounding=ROUND_HALF_UP)
        if rounded != 0 and abs(rounded) >= minimum_trade:
            trades[symbol] = rounded
    return trades

def apply_invoice_payment(self: "CustomerAccount", amount: Decimal, *, invoice_ids: list[str] | None = None, allow_credit: bool = False) -> dict[str, Decimal]:
    if not amount.is_finite() or amount < 0:
        raise ValueError("Payment amount must be finite and nonnegative")
    selected = list(self.outstanding) if invoice_ids is None else list(invoice_ids)
    if len(selected) != len(set(selected)):
        raise ValueError("Invoice selection must not contain duplicates")
    balances = {}
    total_due = Decimal("0")
    for invoice_id in selected:
        if invoice_id not in self.outstanding:
            raise KeyError(f"Unknown invoice {invoice_id}")
        balance = self.outstanding[invoice_id]
        if not balance.is_finite() or balance < 0:
            raise ValueError(f"Invalid outstanding balance for invoice {invoice_id}")
        balances[invoice_id] = balance
        total_due += balance
    if amount > total_due and not allow_credit:
        raise ValueError("Payment exceeds the selected invoices' outstanding balance")
    excess = max(amount - total_due, Decimal("0"))
    if excess > 0:
        credit = self.credit_balance
        if not credit.is_finite() or credit < 0:
            raise ValueError("Existing credit balance must be finite and nonnegative")
        new_credit = credit + excess
    remaining = amount
    allocations = {}
    updated_balances = {}
    for invoice_id in selected:
        if remaining == 0:
            break
        applied = min(remaining, balances[invoice_id])
        if applied > 0:
            allocations[invoice_id] = applied
            updated_balances[invoice_id] = balances[invoice_id] - applied
            remaining -= applied
    self.outstanding.update(updated_balances)
    if excess > 0:
        self.credit_balance = new_credit
    return allocations

def normalize_whitespace(text: str, lowercase: bool = False) -> str:
    parts = text.split()
    normalized = " ".join(parts)
    if lowercase:
        normalized = normalized.lower()
    return normalized

def tokenize_words(text: str, include_numbers: bool = True, lowercase: bool = False) -> list[str]:
    pattern = r"[^\W\d_]+(?:['’][^\W\d_]+)*|\d+(?:[.,]\d+)*"
    tokens: list[str] = []
    for match in re.finditer(pattern, text):
        token = match.group(0)
        is_number = token[0].isdecimal()
        if is_number and not include_numbers:
            continue
        if lowercase:
            token = token.lower()
        tokens.append(token)
    return tokens

def parse_escaped_assignments(text: str, *, separator: str = ";", allow_duplicates: bool = False) -> dict[str, str]:
    if len(separator) != 1 or separator in "\\=":
        raise ValueError("Separator must be one character other than backslash or equals")
    result: dict[str, str] = {}
    key: list[str] = []
    value: list[str] = []
    in_value = False
    escaped = False
    for index, character in enumerate(text + separator):
        target = value if in_value else key
        if escaped:
            if index == len(text):
                raise ValueError("Input ends with an incomplete escape")
            target.append(character)
            escaped = False
        elif character == "\\":
            escaped = True
        elif character == "=" and not in_value:
            in_value = True
        elif character == separator:
            name = "".join(key).strip()
            if not in_value and not name:
                key.clear()
                continue
            if not in_value:
                raise ValueError(f"Assignment has no equals sign: {name}")
            if not name:
                raise ValueError("Assignment key must not be empty")
            if name in result and not allow_duplicates:
                raise ValueError(f"Duplicate assignment key: {name}")
            result[name] = "".join(value).strip()
            key.clear()
            value.clear()
            in_value = False
        else:
            target.append(character)
    return result

def find_search_snippets(text: str, query: str, *, context: int = 30, case_sensitive: bool = False, whole_words: bool = False, max_matches: int = 100) -> list[tuple[int, int, str]]:
    if not query:
        raise ValueError("Search query must not be empty")
    if context < 0:
        raise ValueError("Context length must not be negative")
    if max_matches < 1:
        raise ValueError("Maximum match count must be positive")
    pattern = re.escape(query)
    if whole_words:
        pattern = r"(?<!\w)" + pattern + r"(?!\w)"
    flags = 0 if case_sensitive else re.IGNORECASE
    windows: list[tuple[int, int]] = []
    count = 0
    for match in re.finditer(pattern, text, flags):
        start = max(0, match.start() - context)
        end = min(len(text), match.end() + context)
        if windows and start <= windows[-1][1]:
            previous_start, previous_end = windows[-1]
            windows[-1] = (previous_start, max(previous_end, end))
        else:
            windows.append((start, end))
        count += 1
        if count >= max_matches:
            break
    snippets: list[tuple[int, int, str]] = []
    for start, end in windows:
        snippets.append((start, end, text[start:end]))
    return snippets

def iter_price_changes(prices: list[float]) -> Iterator[tuple[int, float]]:
    for index in range(1, len(prices)):
        previous_price = prices[index - 1]
        current_price = prices[index]
        change = current_price - previous_price
        yield index, change

def iter_monthly_interest(balance: float, annual_rate: float) -> Iterator[tuple[int, float, float]]:
    monthly_rate = annual_rate / 12
    for month in range(1, 13):
        interest = balance * monthly_rate
        balance += interest
        yield month, interest, balance

def iter_invoice_installments(total: Decimal, installments: int, first_due: date, interval_days: int = 30) -> Iterator[tuple[date, Decimal]]:
    if not total.is_finite() or total < 0:
        raise ValueError("Invoice total must be finite and nonnegative")
    if installments < 1:
        raise ValueError("Installment count must be positive")
    if interval_days < 0:
        raise ValueError("Installment interval cannot be negative")
    cent = Decimal("0.01")
    rounded_total = total.quantize(cent, rounding="ROUND_HALF_UP")
    regular_amount = (rounded_total / installments).quantize(cent, rounding="ROUND_DOWN")
    remaining = rounded_total
    for index in range(installments):
        amount = remaining if index == installments - 1 else regular_amount
        due_date = first_due + timedelta(days=index * interval_days)
        remaining -= amount
        yield due_date, amount

def iter_currency_conversions(amounts: Iterable[Decimal], exchange_rate: Decimal, fee: Decimal = Decimal("0"), decimal_places: int = 2) -> Iterator[Decimal]:
    if not exchange_rate.is_finite() or exchange_rate <= 0:
        raise ValueError("Exchange rate must be finite and positive")
    if not fee.is_finite() or fee < 0:
        raise ValueError("Conversion fee must be finite and nonnegative")
    if not 0 <= decimal_places <= 8:
        raise ValueError("Decimal places must be between zero and eight")
    quantum = Decimal("1").scaleb(-decimal_places)
    for amount in amounts:
        if not amount.is_finite() or amount < 0:
            raise ValueError("Source amounts must be finite and nonnegative")
        converted = amount * exchange_rate
        if converted < fee:
            raise ValueError("Conversion fee exceeds the converted amount")
        net_amount = converted - fee
        yield net_amount.quantize(quantum, rounding="ROUND_HALF_UP")

def iter_loan_amortization(principal: Decimal, annual_rate: Decimal, *, monthly_payment: Decimal, extra_payments: dict[int, Decimal] | None = None, max_months: int = 600) -> Iterator[tuple[int, Decimal, Decimal, Decimal]]:
    if not principal.is_finite() or principal <= 0:
        raise ValueError("Principal must be finite and positive")
    if not annual_rate.is_finite() or annual_rate < 0:
        raise ValueError("Annual rate must be finite and nonnegative")
    if not monthly_payment.is_finite() or monthly_payment <= 0:
        raise ValueError("Monthly payment must be finite and positive")
    if max_months < 1:
        raise ValueError("Maximum month count must be positive")
    extras = dict(extra_payments) if extra_payments is not None else {}
    for month, amount in extras.items():
        if not isinstance(month, int) or month < 1:
            raise ValueError("Extra-payment months must be positive integers")
        if not amount.is_finite() or amount < 0:
            raise ValueError("Extra payments must be finite and nonnegative")
    cent = Decimal("0.01")
    balance = principal.quantize(cent, rounding="ROUND_HALF_UP")
    payment = monthly_payment.quantize(cent, rounding="ROUND_HALF_UP")
    if balance == 0 or payment == 0:
        raise ValueError("Principal and payment must round to at least one cent")
    monthly_rate = annual_rate / Decimal("12")
    for month in range(1, max_months + 1):
        interest = (balance * monthly_rate).quantize(cent, rounding="ROUND_HALF_UP")
        extra = extras.get(month, Decimal("0")).quantize(cent, rounding="ROUND_HALF_UP")
        scheduled_payment = payment + extra
        if scheduled_payment <= interest:
            raise ValueError("Scheduled payment does not reduce the loan balance")
        actual_payment = min(scheduled_payment, balance + interest)
        principal_paid = actual_payment - interest
        balance -= principal_paid
        yield month, interest, principal_paid, balance
        if balance == 0:
            return
    raise TimeoutError("Loan was not repaid within the maximum month count")

def iter_rebalance_trades(holdings: dict[str, float], prices: dict[str, float], target_weights: dict[str, float], *, cash: float = 0.0, minimum_trade_value: float = 0.0) -> Iterator[tuple[str, float, float]]:
    if not math.isfinite(cash) or cash < 0:
        raise ValueError("Cash must be finite and nonnegative")
    if not math.isfinite(minimum_trade_value) or minimum_trade_value < 0:
        raise ValueError("Minimum trade value must be finite and nonnegative")
    if not target_weights:
        raise ValueError("At least one target weight is required")
    for weight in target_weights.values():
        if not math.isfinite(weight) or not 0 <= weight <= 1:
            raise ValueError("Target weights must be finite and between zero and one")
    if not math.isclose(math.fsum(target_weights.values()), 1.0, rel_tol=0.0, abs_tol=1e-9):
        raise ValueError("Target weights must sum to one")
    symbols = sorted(set(holdings) | set(target_weights))
    position_values = {}
    for symbol in symbols:
        if symbol not in prices:
            raise KeyError(f"Missing price for {symbol}")
        price = prices[symbol]
        shares = holdings.get(symbol, 0.0)
        if not math.isfinite(price) or price <= 0:
            raise ValueError(f"Price for {symbol} must be finite and positive")
        if not math.isfinite(shares) or shares < 0:
            raise ValueError(f"Holdings for {symbol} must be finite and nonnegative")
        position_values[symbol] = shares * price
    portfolio_value = cash + sum(position_values.values())
    if not math.isfinite(portfolio_value):
        raise ValueError("Portfolio value exceeds the finite numeric range")
    trades = []
    for symbol in symbols:
        target_value = portfolio_value * target_weights.get(symbol, 0.0)
        trade_value = target_value - position_values[symbol]
        if trade_value == 0 or abs(trade_value) < minimum_trade_value:
            continue
        trades.append((symbol, trade_value / prices[symbol], trade_value))
    for trade in sorted(trades, key=lambda item: (item[2] >= 0, item[0])):
        yield trade

def inclusive_date_count(start: date, end: date) -> int:
    if end < start:
        raise ValueError("End date must not precede start date")
    elapsed = end - start
    return elapsed.days + 1

def advance_business_days(start: date, days: int, holidays: frozenset[date] = frozenset()) -> date:
    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError("Days must be an integer")
    current = start
    remaining = abs(days)
    direction = 1 if days >= 0 else -1
    step = timedelta(days=direction)
    while remaining:
        current += step
        if current.weekday() >= 5:
            continue
        if current in holidays:
            continue
        remaining -= 1
    return current

def monthly_pay_dates(reference: date, payday: int = 25, count: int = 6) -> list[date]:
    if not 1 <= payday <= 31:
        raise ValueError("Payday must be between 1 and 31")
    if count < 0:
        raise ValueError("Count must not be negative")
    results = []
    year, month = reference.year, reference.month
    while len(results) < count:
        last_day = calendar.monthrange(year, month)[1]
        candidate = date(year, month, min(payday, last_day))
        if candidate >= reference:
            results.append(candidate)
        if len(results) == count:
            break
        if month == 12:
            year, month = year + 1, 1
        else:
            month += 1
    return results

def resolve_local_appointment(day: date, clock: time, *, zone_name: str, ambiguity: str = "reject") -> datetime:
    if ambiguity not in {"reject", "earlier", "later"}:
        raise ValueError("Ambiguity must be reject, earlier, or later")
    if clock.tzinfo is not None:
        raise ValueError("Appointment clock time must not contain a time zone")
    try:
        zone = ZoneInfo(zone_name)
    except ZoneInfoNotFoundError:
        raise ValueError("Unknown time zone: " + zone_name) from None
    local = datetime.combine(day, clock).replace(fold=0)
    candidates = {}
    for fold in (0, 1):
        candidate = local.replace(tzinfo=zone, fold=fold)
        instant = candidate.astimezone(timezone.utc)
        restored = instant.astimezone(zone)
        wall_time = restored.replace(tzinfo=None, fold=0)
        if wall_time == local:
            candidates[instant] = restored
    instants = sorted(candidates)
    if not instants:
        raise ValueError("Appointment falls in a nonexistent local time")
    if len(instants) == 1:
        return candidates[instants[0]]
    if ambiguity == "reject":
        raise ValueError("Appointment falls in an ambiguous local time")
    if ambiguity == "earlier":
        return candidates[instants[0]]
    return candidates[instants[-1]]

def merge_calendar_bookings(bookings: list[tuple[datetime, datetime]], *, gap: timedelta = timedelta(0), merge_touching: bool = True) -> list[tuple[datetime, datetime]]:
    if gap < timedelta(0):
        raise ValueError("Merge gap must not be negative")
    normalized = []
    for start, end in bookings:
        if start.utcoffset() is None or end.utcoffset() is None:
            raise ValueError("Booking endpoints must be time-zone aware")
        start_utc = start.astimezone(timezone.utc)
        end_utc = end.astimezone(timezone.utc)
        if end_utc < start_utc:
            raise ValueError("Booking end must not precede its start")
        if end_utc == start_utc:
            continue
        normalized.append((start_utc, end_utc))
    normalized.sort()
    merged = []
    for start, end in normalized:
        if not merged:
            merged.append((start, end))
            continue
        previous_start, previous_end = merged[-1]
        separation = start - previous_end
        overlaps = separation < timedelta(0)
        touches = separation == timedelta(0) and merge_touching
        nearby = timedelta(0) < separation <= gap
        if overlaps or touches or nearby:
            merged[-1] = (previous_start, max(previous_end, end))
        else:
            merged.append((start, end))
    return merged

def month_bounds(self: object, day: date) -> tuple[date, date]:
    first = day.replace(day=1)
    if first.month == 12:
        following = first.replace(year=first.year + 1, month=1)
    else:
        following = first.replace(month=first.month + 1)
    last = following - timedelta(days=1)
    return first, last

def seconds_until(self: object, target: datetime) -> int:
    now = datetime.now(target.tzinfo)
    remaining = target - now
    seconds = remaining.total_seconds()
    return max(0, math.ceil(seconds))

def shift_business_days(self: object, start: date, days: int, holidays: set[date] | None = None) -> date:
    excluded = set() if holidays is None else holidays
    if days == 0:
        return start
    direction = 1 if days > 0 else -1
    remaining = abs(days)
    current = start
    step = timedelta(days=direction)
    while remaining:
        current += step
        if current.weekday() >= 5:
            continue
        if current in excluded:
            continue
        remaining -= 1
    return current

def merge_busy_periods(self: object, periods: list[tuple[datetime, datetime]], gap: timedelta = timedelta(0)) -> list[tuple[datetime, datetime]]:
    if gap < timedelta(0):
        raise ValueError('The merge gap must not be negative')
    for start, end in periods:
        if end < start:
            raise ValueError('A busy period must end on or after its start')
    ordered = sorted(periods)
    merged: list[tuple[datetime, datetime]] = []
    for start, end in ordered:
        if not merged:
            merged.append((start, end))
            continue
        previous_start, previous_end = merged[-1]
        if start - previous_end <= gap:
            merged[-1] = (previous_start, max(previous_end, end))
        else:
            merged.append((start, end))
    return merged

def resolve_local_time(self: object, wall: datetime, *, zone: str, ambiguous: str = 'raise', nonexistent: str = 'raise') -> datetime:
    if wall.tzinfo is not None:
        raise ValueError('The wall time must have no time zone attached')
    if ambiguous not in {'raise', 'earlier', 'later'}:
        raise ValueError('Ambiguous policy must be raise, earlier, or later')
    if nonexistent not in {'raise', 'shift_forward'}:
        raise ValueError('Nonexistent policy must be raise or shift_forward')
    target_zone = ZoneInfo(zone)
    valid: dict[datetime, datetime] = {}
    forward: list[datetime] = []
    for fold in (0, 1):
        candidate = wall.replace(tzinfo=target_zone, fold=fold)
        instant = candidate.astimezone(timezone.utc)
        restored = instant.astimezone(target_zone)
        restored_wall = restored.replace(tzinfo=None)
        if restored_wall == wall:
            valid[instant] = restored
        elif restored_wall > wall:
            forward.append(restored)
    if len(valid) == 1:
        return next(iter(valid.values()))
    if len(valid) == 2:
        if ambiguous == 'raise':
            raise ValueError('The wall time occurs twice in the requested zone')
        instants = sorted(valid)
        chosen = instants[0] if ambiguous == 'earlier' else instants[-1]
        return valid[chosen]
    if nonexistent == 'raise':
        raise ValueError('The wall time does not exist in the requested zone')
    if not forward:
        raise ValueError('No forward adjustment is available for this wall time')
    return min(forward, key=lambda value: value.astimezone(timezone.utc))

def business_hour_deadline(self: object, opened: datetime, *, hours: float, opening: time = time(9), closing: time = time(17), holidays: frozenset[date] = frozenset()) -> datetime:
    if opened.tzinfo is not None:
        raise ValueError('The start must be a naive local datetime')
    if opening.tzinfo is not None or closing.tzinfo is not None:
        raise ValueError('Business hours must be naive local times')
    if closing <= opening:
        raise ValueError('Closing time must be later than opening time')
    if not math.isfinite(hours) or hours < 0:
        raise ValueError('Hours must be finite and nonnegative')
    remaining = timedelta(hours=hours)
    if remaining == timedelta(0):
        return opened
    current = opened
    while remaining > timedelta(0):
        day = current.date()
        if day.weekday() >= 5 or day in holidays:
            current = datetime.combine(day + timedelta(days=1), opening)
            continue
        day_start = datetime.combine(day, opening)
        day_end = datetime.combine(day, closing)
        if current < day_start:
            current = day_start
        elif current >= day_end:
            current = datetime.combine(day + timedelta(days=1), opening)
            continue
        available = day_end - current
        if remaining <= available:
            return current + remaining
        remaining -= available
        current = datetime.combine(day + timedelta(days=1), opening)
    return current

def read_nonempty_lines(path: str | Path, encoding: str = "utf-8") -> list[str]:
    lines: list[str] = []
    with open(path, "r", encoding=encoding) as handle:
        for line in handle:
            text = line.strip()
            if text:
                lines.append(text)
    return lines

def read_csv_columns(path: str | Path, columns: tuple[str, ...], skip_blank: bool = True, delimiter: str = ",") -> list[dict[str, str]]:
    if len(delimiter) != 1:
        raise ValueError("CSV delimiter must be exactly one character")
    records: list[dict[str, str]] = []
    with open(path, "r", encoding="utf-8-sig", newline="") as handle:
        reader = csv.DictReader(handle, delimiter=delimiter)
        headers = reader.fieldnames or []
        missing = set(columns) - set(headers)
        if missing:
            raise ValueError(f"Missing CSV columns: {', '.join(sorted(missing))}")
        if len(headers) != len(set(headers)):
            raise ValueError("CSV headers must be unique")
        for row in reader:
            if None in row or any(value is None for value in row.values()):
                raise ValueError(f"Malformed CSV record ending on line {reader.line_num}")
            record = {column: row[column] for column in columns}
            if skip_blank and not any(value.strip() for value in record.values()):
                continue
            records.append(record)
    return records

def load_config_section(path: str | Path, section: str, defaults: dict[str, str] | None = None) -> dict[str, str]:
    parser = configparser.ConfigParser(interpolation=None)
    parser.optionxform = str
    with open(path, "r", encoding="utf-8") as handle:
        parser.read_file(handle)
    settings = dict(defaults) if defaults is not None else {}
    if section == parser.default_section:
        settings.update(parser.defaults())
    elif parser.has_section(section):
        settings.update(dict(parser.items(section)))
    else:
        raise KeyError(f"Configuration section not found: {section}")
    return settings

def resolve_workspace_path(root: str | Path, relative_path: str | Path, *, must_exist: bool = False, kind: str = "any") -> Path:
    if kind not in {"any", "file", "directory"}:
        raise ValueError("Path kind must be 'any', 'file', or 'directory'")
    workspace = Path(root).resolve(strict=True)
    if not workspace.is_dir():
        raise NotADirectoryError(f"Workspace is not a directory: {workspace}")
    requested = Path(relative_path)
    if requested.is_absolute() or requested.anchor:
        raise ValueError("Workspace paths must be relative")
    candidate = (workspace / requested).resolve(strict=False)
    if not candidate.is_relative_to(workspace):
        raise ValueError("Requested path escapes the workspace")
    exists = candidate.exists()
    if must_exist and not exists:
        raise FileNotFoundError(f"Workspace path does not exist: {candidate}")
    if exists and kind == "file" and not candidate.is_file():
        raise ValueError(f"Expected a regular file: {candidate}")
    if exists and kind == "directory" and not candidate.is_dir():
        raise NotADirectoryError(f"Expected a directory: {candidate}")
    return candidate

def concatenate_files_atomically(*sources: str | Path, destination: str | Path, overwrite: bool = False) -> int:
    if not sources:
        raise ValueError("At least one source file is required")
    target = Path(destination).absolute()
    if not target.parent.is_dir():
        raise FileNotFoundError(f"Destination directory does not exist: {target.parent}")
    if target.is_dir():
        raise IsADirectoryError(f"Destination is a directory: {target}")
    if os.path.lexists(target) and not overwrite:
        raise FileExistsError(f"Destination already exists: {target}")
    paths = [Path(source) for source in sources]
    for source in paths:
        if not source.exists():
            raise FileNotFoundError(f"Source file does not exist: {source}")
        if not source.is_file():
            raise ValueError(f"Source is not a regular file: {source}")
        if source.resolve() == target.resolve():
            raise ValueError("Destination cannot also be a source file")
    temporary: Path | None = None
    total = 0
    try:
        with tempfile.NamedTemporaryFile(mode="wb", dir=target.parent, delete=False) as output:
            temporary = Path(output.name)
            for source in paths:
                with source.open("rb") as input_file:
                    while chunk := input_file.read(1024 * 1024):
                        output.write(chunk)
                        total += len(chunk)
            output.flush()
            os.fsync(output.fileno())
        if overwrite:
            os.replace(temporary, target)
        else:
            os.link(temporary, target)
        return total
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)

def append_log_entry(self: "FileStore", message: str) -> int:
    destination = Path(self.log_path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    entry = message.rstrip("\r\n") + "\n"
    with destination.open("a", encoding="utf-8") as handle:
        return handle.write(entry)

def read_csv_records(self: "FileStore", path: str | Path, required_columns: tuple[str, ...] = (), delimiter: str = ",") -> list[dict[str, str]]:
    if len(delimiter) != 1:
        raise ValueError("CSV delimiter must be one character")
    with Path(path).open("r", encoding="utf-8-sig", newline="") as handle:
        reader = csv.DictReader(handle, delimiter=delimiter)
        headers = reader.fieldnames
        if headers is None:
            raise ValueError("CSV file has no header")
        if len(headers) != len(set(headers)):
            raise ValueError("CSV headers must be unique")
        missing = set(required_columns) - set(headers)
        if missing:
            raise ValueError(f"Missing CSV columns: {', '.join(sorted(missing))}")
        records = []
        for row in reader:
            if None in row or any(value is None for value in row.values()):
                raise ValueError(f"Malformed CSV record ending on line {reader.line_num}")
            records.append(row)
    return records

def update_ini_section(self: "FileStore", path: str | Path, updates: dict[str, str], section: str = "general") -> int:
    if not section:
        raise ValueError("INI section name must not be empty")
    destination = Path(path)
    parser = configparser.ConfigParser(interpolation=None)
    parser.optionxform = str
    if destination.exists():
        with destination.open("r", encoding="utf-8") as handle:
            parser.read_file(handle)
    if section != parser.default_section and not parser.has_section(section):
        parser.add_section(section)
    changed = 0
    for key, value in updates.items():
        if not parser.has_option(section, key) or parser.get(section, key) != value:
            parser.set(section, key, value)
            changed += 1
    destination.parent.mkdir(parents=True, exist_ok=True)
    with destination.open("w", encoding="utf-8") as handle:
        parser.write(handle)
    return changed

def inventory_directory(self: "FileStore", root: str | Path, *, recursive: bool = True, include_hidden: bool = False, suffixes: tuple[str, ...] = (), minimum_size: int = 0) -> list[dict[str, str | int]]:
    if isinstance(minimum_size, bool) or not isinstance(minimum_size, int):
        raise TypeError("Minimum file size must be an integer")
    if minimum_size < 0:
        raise ValueError("Minimum file size must not be negative")
    base = Path(root)
    if not base.exists():
        raise FileNotFoundError(f"Directory does not exist: {base}")
    if not base.is_dir():
        raise NotADirectoryError(f"Inventory root is not a directory: {base}")
    allowed = set()
    for suffix in suffixes:
        if not suffix or not suffix.startswith("."):
            raise ValueError("Each suffix must begin with a dot")
        allowed.add(suffix.casefold())
    entries = base.rglob("*") if recursive else base.iterdir()
    records = []
    for entry in entries:
        relative = entry.relative_to(base)
        if not include_hidden and any(part.startswith(".") for part in relative.parts):
            continue
        try:
            metadata = entry.lstat()
        except FileNotFoundError:
            continue
        if not stat.S_ISREG(metadata.st_mode):
            continue
        if allowed and entry.suffix.casefold() not in allowed:
            continue
        if metadata.st_size < minimum_size:
            continue
        records.append({"path": relative.as_posix(), "size": metadata.st_size, "modified_ns": metadata.st_mtime_ns})
    records.sort(key=lambda record: record["path"])
    return records

def iter_nonempty_lines(path: str, encoding: str = "utf-8") -> Iterator[str]:
    with open(path, "r", encoding=encoding) as source:
        for line in source:
            text = line.rstrip("\r\n")
            if not text.strip():
                continue
            yield text

def iter_directory_files(directory: str) -> Iterator[Path]:
    root = Path(directory)
    entries = sorted(root.iterdir(), key=lambda entry: entry.name)
    for entry in entries:
        if not entry.is_file():
            continue
        yield entry

def iter_csv_batches(path: str, batch_size: int = 100, skip_header: bool = False) -> Iterator[list[list[str]]]:
    if batch_size <= 0:
        raise ValueError("batch_size must be positive")
    with open(path, "r", encoding="utf-8-sig", newline="") as source:
        reader = csv.reader(source)
        if skip_header:
            next(reader, None)
        batch: list[list[str]] = []
        for row in reader:
            batch.append(row)
            if len(batch) == batch_size:
                yield batch
                batch = []
        if batch:
            yield batch

def iter_json_objects(path: str, skip_invalid: bool = False, encoding: str = "utf-8") -> Iterator[dict[str, object]]:
    with open(path, "r", encoding=encoding) as source:
        for line_number, line in enumerate(source, start=1):
            if not line.strip():
                continue
            try:
                value = json.loads(line)
            except json.JSONDecodeError as error:
                if skip_invalid:
                    continue
                raise ValueError(f"Invalid JSON on line {line_number}") from error
            if not isinstance(value, dict):
                if skip_invalid:
                    continue
                raise ValueError(f"Expected a JSON object on line {line_number}")
            yield value

def iter_config_entries(path: str, *, allow_duplicates: bool = False, encoding: str = "utf-8") -> Iterator[tuple[str, str, str]]:
    section = ""
    seen: set[tuple[str, str]] = set()
    with open(path, "r", encoding=encoding) as source:
        for line_number, raw_line in enumerate(source, start=1):
            line = raw_line.strip()
            if not line or line.startswith(("#", ";")):
                continue
            if line.startswith("["):
                if not line.endswith("]"):
                    raise ValueError(f"Unclosed section on line {line_number}")
                section = line[1:-1].strip()
                if not section or "[" in section or "]" in section:
                    raise ValueError(f"Invalid section name on line {line_number}")
                continue
            if "=" not in line:
                raise ValueError(f"Missing assignment on line {line_number}")
            key, value = line.split("=", 1)
            key = key.strip()
            value = value.strip()
            if not key:
                raise ValueError(f"Empty key on line {line_number}")
            identity = (section, key)
            if identity in seen and not allow_duplicates:
                raise ValueError(f"Duplicate key {key!r} in section {section!r}")
            seen.add(identity)
            yield section, key, value

def iter_binary_records(path: str, *, record_size: int, offset: int = 0, incomplete: str = "error") -> Iterator[bytes]:
    if record_size <= 0:
        raise ValueError("record_size must be positive")
    if offset < 0:
        raise ValueError("offset must not be negative")
    if incomplete not in {"error", "drop", "keep"}:
        raise ValueError("incomplete must be 'error', 'drop', or 'keep'")
    with open(path, "rb") as source:
        source.seek(offset)
        record_number = 0
        while True:
            record = source.read(record_size)
            if not record:
                return
            record_number += 1
            if len(record) == record_size:
                yield record
                continue
            if incomplete == "error":
                raise ValueError(f"Record {record_number} has {len(record)} bytes; expected {record_size}")
            if incomplete == "keep":
                yield record
            return

async def count_business_days(start: date, end: date, client: Any, include_end: bool = False) -> int:
    if end < start:
        raise ValueError("End date must not precede start date")
    holiday_strings = await client.fetch_holidays(start, end)
    holidays = {date.fromisoformat(value) for value in holiday_strings}
    count = 0
    current = start
    while current < end:
        if current.weekday() < 5 and current not in holidays:
            count += 1
        current += timedelta(days=1)
    if include_end and end.weekday() < 5 and end not in holidays:
        count += 1
    return count

async def fetch_free_calendar_windows(client: Any, window_start: datetime, window_end: datetime, *, buffer: timedelta = timedelta(0)) -> list[tuple[datetime, datetime]]:
    if window_start.utcoffset() is None or window_end.utcoffset() is None:
        raise ValueError("Window boundaries must be timezone-aware")
    start = window_start.astimezone(timezone.utc)
    end = window_end.astimezone(timezone.utc)
    if end <= start:
        raise ValueError("Window end must be after window start")
    if buffer < timedelta(0):
        raise ValueError("Buffer must not be negative")
    bookings = await client.fetch_busy(start - buffer, end + buffer)
    blocked: list[tuple[datetime, datetime]] = []
    for busy_start, busy_end in bookings:
        if busy_start.utcoffset() is None or busy_end.utcoffset() is None:
            raise ValueError("Booking boundaries must be timezone-aware")
        busy_start = busy_start.astimezone(timezone.utc)
        busy_end = busy_end.astimezone(timezone.utc)
        if busy_end < busy_start:
            raise ValueError("Booking end must not precede booking start")
        if busy_start == busy_end:
            continue
        left = max(start, busy_start - buffer)
        right = min(end, busy_end + buffer)
        if left < right:
            blocked.append((left, right))
    blocked.sort()
    free: list[tuple[datetime, datetime]] = []
    cursor = start
    for left, right in blocked:
        if left > cursor:
            free.append((cursor, left))
        cursor = max(cursor, right)
        if cursor >= end:
            break
    if cursor < end:
        free.append((cursor, end))
    return free

async def wait_for_event_start(client: Any, event_id: str, *, timeout: float = 30.0, poll_interval: float = 1.0) -> datetime:
    if not math.isfinite(timeout) or timeout <= 0:
        raise ValueError("Timeout must be finite and positive")
    if not math.isfinite(poll_interval) or poll_interval <= 0:
        raise ValueError("Poll interval must be finite and positive")
    loop = asyncio.get_running_loop()
    deadline = loop.time() + timeout
    while True:
        remaining = deadline - loop.time()
        if remaining <= 0:
            raise TimeoutError("Event did not start before the timeout")
        try:
            event = await asyncio.wait_for(client.fetch_event(event_id), timeout=remaining)
        except TimeoutError:
            raise TimeoutError("Event lookup exceeded the timeout") from None
        status = event.get("status")
        if status == "cancelled":
            raise ValueError("Event was cancelled")
        if status not in {"pending", "scheduled"}:
            raise ValueError("Event has an unsupported status")
        delay = poll_interval
        if status == "scheduled":
            if "starts_at" not in event:
                raise KeyError("Scheduled event has no starts_at timestamp")
            starts_at = datetime.fromisoformat(event["starts_at"])
            if starts_at.utcoffset() is None:
                raise ValueError("Event start must be timezone-aware")
            starts_at = starts_at.astimezone(timezone.utc)
            seconds_until_start = (starts_at - datetime.now(timezone.utc)).total_seconds()
            if seconds_until_start <= 0:
                return starts_at
            delay = min(delay, seconds_until_start)
        remaining = deadline - loop.time()
        if remaining <= 0:
            raise TimeoutError("Event did not start before the timeout")
        await asyncio.sleep(min(delay, remaining))

def consecutive_dates(start: date, count: int) -> Iterator[date]:
    if count < 0:
        raise ValueError("count must be nonnegative")
    for offset in range(count):
        yield start + timedelta(days=offset)

def countdown_durations(total: timedelta, step: timedelta) -> Iterator[timedelta]:
    if total < timedelta(0) or step <= timedelta(0):
        raise ValueError("total must be nonnegative and step must be positive")
    remaining = total
    while remaining > timedelta(0):
        yield remaining
        remaining = max(timedelta(0), remaining - step)
    yield timedelta(0)

def business_dates(start: date, count: int, holidays: set[date] | None = None) -> Iterator[date]:
    if count < 0:
        raise ValueError("count must be nonnegative")
    excluded = set() if holidays is None else set(holidays)
    current = start
    remaining = count
    while remaining:
        if current.weekday() < 5 and current not in excluded:
            yield current
            remaining -= 1
            if remaining == 0:
                return
        current += timedelta(days=1)

def split_time_window(start: datetime, end: datetime, width: timedelta = timedelta(hours=1), keep_partial: bool = True) -> Iterator[tuple[datetime, datetime]]:
    if width <= timedelta(0):
        raise ValueError("width must be positive")
    aware = start.utcoffset() is not None
    if aware != (end.utcoffset() is not None):
        raise ValueError("start and end must both be naive or both be aware")
    output_zone = start.tzinfo
    if aware:
        start = start.astimezone(timezone.utc)
        end = end.astimezone(timezone.utc)
    if end < start:
        raise ValueError("end must not precede start")
    cursor = start
    while cursor < end:
        span = min(width, end - cursor)
        if span < width and not keep_partial:
            return
        stop = cursor + span
        if aware:
            yield cursor.astimezone(output_zone), stop.astimezone(output_zone)
        else:
            yield cursor, stop
        cursor = stop

def monthly_payment_dates(start: date, end: date, *, day_of_month: int = 31, missing_day: str = "clamp") -> Iterator[date]:
    if not 1 <= day_of_month <= 31:
        raise ValueError("day_of_month must be between 1 and 31")
    if missing_day not in {"clamp", "skip", "raise"}:
        raise ValueError("missing_day must be clamp, skip, or raise")
    if end < start:
        raise ValueError("end must not precede start")
    year, month = start.year, start.month
    while (year, month) <= (end.year, end.month):
        last_day = calendar.monthrange(year, month)[1]
        selected_day = day_of_month
        if selected_day > last_day:
            if missing_day == "raise":
                raise ValueError(f"day {day_of_month} does not exist in {year:04d}-{month:02d}")
            if missing_day == "skip":
                selected_day = 0
            else:
                selected_day = last_day
        if selected_day:
            payment_date = date(year, month, selected_day)
            if start <= payment_date <= end:
                yield payment_date
        if (year, month) == (end.year, end.month):
            return
        if month == 12:
            year += 1
            month = 1
        else:
            month += 1

def zoned_daily_occurrences(start: date, days: int, *, local_time: time, zone: str, ambiguous: str = "both", nonexistent: str = "skip") -> Iterator[datetime]:
    if days < 0:
        raise ValueError("days must be nonnegative")
    if local_time.tzinfo is not None:
        raise ValueError("local_time must not contain a time zone")
    if ambiguous not in {"both", "earlier", "later", "raise"}:
        raise ValueError("ambiguous must be both, earlier, later, or raise")
    if nonexistent not in {"skip", "raise"}:
        raise ValueError("nonexistent must be skip or raise")
    try:
        target_zone = ZoneInfo(zone)
    except KeyError as exc:
        raise ValueError(f"unknown time zone: {zone}") from exc
    for offset in range(days):
        wall = datetime.combine(start + timedelta(days=offset), local_time)
        matches: dict[datetime, datetime] = {}
        for fold in (0, 1):
            candidate = wall.replace(tzinfo=target_zone, fold=fold)
            instant = candidate.astimezone(timezone.utc)
            restored = instant.astimezone(target_zone)
            if restored.replace(tzinfo=None) == wall:
                matches[instant] = restored
        if not matches:
            if nonexistent == "raise":
                raise ValueError(f"local time does not exist: {wall.isoformat()} in {zone}")
            continue
        instants = sorted(matches)
        if len(instants) > 1:
            if ambiguous == "raise":
                raise ValueError(f"local time is ambiguous: {wall.isoformat()} in {zone}")
            if ambiguous == "earlier":
                instants = instants[:1]
            elif ambiguous == "later":
                instants = instants[-1:]
        for instant in instants:
            yield matches[instant]

async def read_ini_section(path: str | Path, section: str, *, defaults: dict[str, str] | None = None, required_keys: tuple[str, ...] = ()) -> dict[str, str]:
    if not section.strip():
        raise ValueError("A nonempty configuration section name is required")
    if section == "DEFAULT":
        raise ValueError("DEFAULT is not a selectable configuration section")
    target = Path(path)
    content = await asyncio.to_thread(target.read_text, encoding="utf-8-sig")
    parser = configparser.ConfigParser(defaults=defaults, interpolation=None)
    try:
        parser.read_string(content, source=str(target))
    except configparser.Error as exc:
        raise ValueError(f"Invalid INI configuration in {target}: {exc}") from exc
    if not parser.has_section(section):
        raise KeyError(f"Configuration section not found: {section}")
    values = dict(parser.items(section))
    missing = []
    for key in required_keys:
        normalized = parser.optionxform(key)
        if normalized not in values:
            missing.append(key)
        elif not values[normalized].strip():
            raise ValueError(f"Required configuration value is empty: {key}")
    if missing:
        raise KeyError(f"Missing configuration keys: {', '.join(missing)}")
    return values

def arithmetic_mean(values: list[float]) -> float:
    if not values:
        raise ValueError("Cannot compute the mean of an empty list")
    numbers = [float(value) for value in values]
    if not all(math.isfinite(value) for value in numbers):
        raise ValueError("Mean requires finite values")
    return math.fsum(value / len(numbers) for value in numbers)

def sample_median(values: list[float]) -> float:
    if not values:
        raise ValueError("Cannot compute the median of an empty list")
    ordered = sorted(float(value) for value in values)
    if not all(math.isfinite(value) for value in ordered):
        raise ValueError("Median requires finite values")
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return ordered[middle - 1] / 2 + ordered[middle] / 2

def sample_percentile(values: list[float], percentile: float, method: str = "linear") -> float:
    if not values:
        raise ValueError("Percentiles require at least one value")
    if not math.isfinite(percentile) or not 0 <= percentile <= 100:
        raise ValueError("Percentile must be finite and between 0 and 100")
    if method not in {"linear", "lower", "higher"}:
        raise ValueError("Method must be linear, lower, or higher")
    ordered = sorted(float(value) for value in values)
    if not all(math.isfinite(value) for value in ordered):
        raise ValueError("Percentiles require finite values")
    position = (len(ordered) - 1) * (percentile / 100)
    lower = math.floor(position)
    upper = math.ceil(position)
    if method == "lower":
        return ordered[lower]
    if method == "higher":
        return ordered[upper]
    fraction = position - lower
    return ordered[lower] * (1 - fraction) + ordered[upper] * fraction

def trailing_moving_average(values: list[float | None], window: int, min_periods: int | None = None) -> list[float | None]:
    if isinstance(window, bool) or not isinstance(window, int) or window < 1:
        raise ValueError("Window must be a positive integer")
    required = window if min_periods is None else min_periods
    if isinstance(required, bool) or not isinstance(required, int) or not 1 <= required <= window:
        raise ValueError("Minimum periods must be an integer between 1 and window")
    numbers = [None if value is None else float(value) for value in values]
    if any(value is not None and not math.isfinite(value) for value in numbers):
        raise ValueError("Nonmissing values must be finite")
    result: list[float | None] = []
    for end in range(len(numbers)):
        start = max(0, end - window + 1)
        observed = [value for value in numbers[start:end + 1] if value is not None]
        if len(observed) < required:
            result.append(None)
        else:
            average = math.fsum(value / len(observed) for value in observed)
            result.append(average)
    return result

def iqr_outlier_indices(values: list[float], *, multiplier: float = 1.5, side: str = "both") -> list[int]:
    if not math.isfinite(multiplier) or multiplier < 0:
        raise ValueError("IQR multiplier must be finite and nonnegative")
    if side not in {"both", "low", "high"}:
        raise ValueError("Side must be both, low, or high")
    numbers = [float(value) for value in values]
    if not numbers:
        raise ValueError("Outlier detection requires at least one value")
    if not all(math.isfinite(value) for value in numbers):
        raise ValueError("Outlier detection requires finite values")
    ordered = sorted(numbers)
    quartiles: list[float] = []
    for probability in (0.25, 0.75):
        position = (len(ordered) - 1) * probability
        lower = math.floor(position)
        upper = math.ceil(position)
        fraction = position - lower
        quartiles.append(ordered[lower] * (1 - fraction) + ordered[upper] * fraction)
    spread = quartiles[1] - quartiles[0]
    if not math.isfinite(spread):
        raise ValueError("Interquartile range exceeds the floating-point range")
    padding = 0.0 if multiplier == 0 else multiplier * spread
    lower_fence = quartiles[0] - padding
    upper_fence = quartiles[1] + padding
    result: list[int] = []
    for index, value in enumerate(numbers):
        if side in {"both", "low"} and value < lower_fence:
            result.append(index)
        elif side in {"both", "high"} and value > upper_fence:
            result.append(index)
    return result

def weighted_histogram(values: list[float], edges: list[float], *, weights: list[float] | None = None, density: bool = False) -> list[float]:
    boundaries = [float(edge) for edge in edges]
    if len(boundaries) < 2:
        raise ValueError("A histogram requires at least two bin edges")
    if not all(math.isfinite(edge) for edge in boundaries):
        raise ValueError("Bin edges must be finite")
    if any(left >= right for left, right in zip(boundaries, boundaries[1:])):
        raise ValueError("Bin edges must be strictly increasing")
    numbers = [float(value) for value in values]
    if not all(math.isfinite(value) for value in numbers):
        raise ValueError("Histogram values must be finite")
    if weights is None:
        mass = [1.0] * len(numbers)
    else:
        if len(weights) != len(numbers):
            raise ValueError("Weights must match the number of values")
        mass = [float(weight) for weight in weights]
        if any(not math.isfinite(weight) or weight < 0 for weight in mass):
            raise ValueError("Weights must be finite and nonnegative")
    totals = [0.0] * (len(boundaries) - 1)
    for value, weight in zip(numbers, mass):
        if value < boundaries[0] or value > boundaries[-1]:
            continue
        index = min(bisect.bisect_right(boundaries, value) - 1, len(totals) - 1)
        totals[index] += weight
        if not math.isfinite(totals[index]):
            raise ValueError("Bin weight exceeds the floating-point range")
    if density:
        scale = max(totals)
        if scale == 0:
            raise ValueError("Density requires positive weight inside the bins")
        normalized = [total / scale for total in totals]
        total_mass = math.fsum(normalized)
        widths = [right - left for left, right in zip(boundaries, boundaries[1:])]
        if not all(math.isfinite(width) for width in widths):
            raise ValueError("Bin width exceeds the floating-point range")
        return [(total / total_mass) / width for total, width in zip(normalized, widths)]
    return totals

def clean_blank_cells(values: list[object]) -> list[object]:
    cleaned: list[object] = []
    for value in values:
        if isinstance(value, str):
            value = value.strip()
            value = value if value else None
        cleaned.append(value)
    return cleaned

def unique_labels(labels: list[str]) -> list[str]:
    seen: set[str] = set()
    result: list[str] = []
    for label in labels:
        if label not in seen:
            seen.add(label)
            result.append(label)
    return result

def coerce_integer_column(records: list[dict[str, object]], column: str, fallback: int | None = None) -> list[dict[str, object]]:
    result: list[dict[str, object]] = []
    for record in records:
        row = record.copy()
        value = row.get(column)
        converted = fallback
        if isinstance(value, int) and not isinstance(value, bool):
            converted = value
        elif isinstance(value, float) and math.isfinite(value) and value.is_integer():
            converted = int(value)
        elif isinstance(value, str):
            text = value.strip()
            try:
                converted = int(text)
            except ValueError:
                converted = fallback
        row[column] = converted
        result.append(row)
    return result

def map_record_columns(records: list[dict[str, object]], mapping: dict[str, str], keep_unmapped: bool = True) -> list[dict[str, object]]:
    result: list[dict[str, object]] = []
    for record in records:
        renamed: dict[str, object] = {}
        for source, value in record.items():
            if source in mapping:
                target = mapping[source]
            elif keep_unmapped:
                target = source
            else:
                continue
            if target in renamed:
                raise ValueError(f"Multiple columns map to {target!r}")
            renamed[target] = value
        result.append(renamed)
    return result

def forward_fill_records(records: list[dict[str, object]], columns: list[str], *, group_key: str | None = None, max_gap: int | None = None) -> list[dict[str, object]]:
    if max_gap is not None and (isinstance(max_gap, bool) or not isinstance(max_gap, int)):
        raise TypeError("max_gap must be an integer or None")
    if max_gap is not None and max_gap < 0:
        raise ValueError("max_gap must be nonnegative")
    columns = list(dict.fromkeys(columns))
    if group_key is not None and group_key in columns:
        raise ValueError("The grouping column cannot be filled")
    state: dict[object, dict[str, tuple[object, int]]] = {}
    result: list[dict[str, object]] = []
    for record in records:
        row = record.copy()
        group: object = None
        if group_key is not None:
            if group_key not in row:
                raise KeyError(f"Missing grouping column {group_key!r}")
            group = row[group_key]
        try:
            history = state.setdefault(group, {})
        except TypeError:
            raise TypeError("Grouping values must be hashable") from None
        for column in columns:
            value = row.get(column)
            if value is not None:
                history[column] = (value, 0)
            elif column in history:
                previous, gap = history[column]
                gap += 1
                history[column] = (previous, gap)
                if max_gap is None or gap <= max_gap:
                    row[column] = previous
        result.append(row)
    return result

def consolidate_records(records: list[dict[str, object]], key_column: str, *, conflict: str = "error") -> list[dict[str, object]]:
    if conflict not in {"error", "first", "last"}:
        raise ValueError("conflict must be 'error', 'first', or 'last'")
    positions: dict[object, int] = {}
    result: list[dict[str, object]] = []
    for record in records:
        if key_column not in record:
            raise KeyError(f"Missing identity column {key_column!r}")
        identity = record[key_column]
        if identity is None:
            raise ValueError("Record identities cannot be None")
        try:
            position = positions.get(identity)
        except TypeError:
            raise TypeError("Record identities must be hashable") from None
        if position is None:
            positions[identity] = len(result)
            result.append(record.copy())
            continue
        merged = result[position]
        for column, value in record.items():
            if column == key_column:
                continue
            if column not in merged:
                merged[column] = value
            elif value is None:
                continue
            elif merged[column] is None:
                merged[column] = value
            elif merged[column] != value:
                if conflict == "error":
                    raise ValueError(f"Conflicting values for {identity!r} in column {column!r}")
                if conflict == "last":
                    merged[column] = value
    return result

def histogram_heights(self: object, values: list[float], edges: list[float], density: bool = False) -> list[float]:
    boundaries = [float(edge) for edge in edges]
    if len(boundaries) < 2:
        raise ValueError("At least two bin edges are required")
    if any(not math.isfinite(edge) for edge in boundaries):
        raise ValueError("Bin edges must be finite")
    if any(left >= right for left, right in zip(boundaries, boundaries[1:])):
        raise ValueError("Bin edges must be strictly increasing")
    heights = [0.0] * (len(boundaries) - 1)
    for raw_value in values:
        value = float(raw_value)
        if not math.isfinite(value):
            raise ValueError("Sample values must be finite")
        if value < boundaries[0] or value > boundaries[-1]:
            continue
        index = min(bisect.bisect_right(boundaries, value) - 1, len(heights) - 1)
        heights[index] += 1.0
    total = sum(heights)
    if density and total:
        for index in range(len(heights)):
            width = boundaries[index + 1] - boundaries[index]
            heights[index] = heights[index] / total / width
    return heights

def interpolated_percentile(self: object, values: list[float], *, percentile: float = 50.0, method: str = "linear") -> float:
    if method not in {"linear", "lower", "higher", "nearest", "midpoint"}:
        raise ValueError("Unsupported percentile interpolation method")
    requested = float(percentile)
    if not math.isfinite(requested) or not 0.0 <= requested <= 100.0:
        raise ValueError("Percentile must be finite and between 0 and 100")
    numbers = sorted(float(value) for value in values)
    if not numbers:
        raise ValueError("Cannot compute a percentile of an empty sample")
    if any(not math.isfinite(value) for value in numbers):
        raise ValueError("Sample values must be finite")
    position = requested / 100.0 * (len(numbers) - 1)
    lower = math.floor(position)
    upper = math.ceil(position)
    if lower == upper:
        return numbers[lower]
    if method == "lower":
        return numbers[lower]
    if method == "higher":
        return numbers[upper]
    if method == "nearest":
        return numbers[round(position)]
    if method == "midpoint":
        return numbers[lower] / 2.0 + numbers[upper] / 2.0
    fraction = position - lower
    return (1.0 - fraction) * numbers[lower] + fraction * numbers[upper]

async def histogram_with_overflow(values: list[float], edges: list[float], *, include_rightmost: bool = True, out_of_range: str = "count") -> tuple[list[int], int, int]:
    if out_of_range not in {"count", "raise"}:
        raise ValueError("Out-of-range policy must be 'count' or 'raise'")
    boundaries = list(edges)
    if len(boundaries) < 2:
        raise ValueError("A histogram requires at least two bin edges")
    if any(not math.isfinite(edge) for edge in boundaries):
        raise ValueError("Bin edges must be finite")
    if any(left >= right for left, right in zip(boundaries, boundaries[1:])):
        raise ValueError("Bin edges must be strictly increasing")
    samples = list(values)
    counts = [0] * (len(boundaries) - 1)
    underflow = 0
    overflow = 0
    await asyncio.sleep(0)
    for index, value in enumerate(samples):
        if not math.isfinite(value):
            raise ValueError("Histogram observations must be finite")
        if value < boundaries[0]:
            if out_of_range == "raise":
                raise ValueError("Observation falls below the histogram range")
            underflow += 1
        elif value > boundaries[-1] or (value == boundaries[-1] and not include_rightmost):
            if out_of_range == "raise":
                raise ValueError("Observation falls above the histogram range")
            overflow += 1
        elif value == boundaries[-1]:
            counts[-1] += 1
        else:
            bin_index = bisect.bisect_right(boundaries, value) - 1
            counts[bin_index] += 1
        if (index + 1) % 1024 == 0:
            await asyncio.sleep(0)
    return counts, underflow, overflow

async def interquartile_outliers(values: list[float], *, fence_multiplier: float = 1.5, minimum_samples: int = 4, inclusive: bool = False) -> list[tuple[int, float]]:
    if not math.isfinite(fence_multiplier) or fence_multiplier < 0:
        raise ValueError("Fence multiplier must be finite and nonnegative")
    if minimum_samples < 2:
        raise ValueError("Minimum sample count must be at least two")
    samples = list(values)
    if len(samples) < minimum_samples:
        raise ValueError("Not enough observations for outlier detection")
    if any(not math.isfinite(value) for value in samples):
        raise ValueError("Outlier detection requires finite observations")
    await asyncio.sleep(0)
    ordered = sorted(samples)
    quartiles: list[float] = []
    for fraction in (0.25, 0.75):
        position = fraction * (len(ordered) - 1)
        lower = math.floor(position)
        upper = math.ceil(position)
        weight = position - lower
        quartiles.append((1.0 - weight) * ordered[lower] + weight * ordered[upper])
    spread = quartiles[1] - quartiles[0]
    lower_fence = quartiles[0] - fence_multiplier * spread
    upper_fence = quartiles[1] + fence_multiplier * spread
    if not math.isfinite(lower_fence) or not math.isfinite(upper_fence):
        raise ValueError("Outlier fences exceed the finite numeric range")
    flagged: list[tuple[int, float]] = []
    for index, value in enumerate(samples):
        if inclusive:
            outside = value <= lower_fence or value >= upper_fence
        else:
            outside = value < lower_fence or value > upper_fence
        if outside:
            flagged.append((index, float(value)))
        if (index + 1) % 512 == 0:
            await asyncio.sleep(0)
    return flagged

def normalize_missing_text(self: object, values: list[str | None]) -> list[str | None]:
    cleaned: list[str | None] = []
    missing_tokens = {"", "null", "none", "n/a", "na"}
    for value in values:
        text = value.strip() if value is not None else ""
        cleaned.append(None if text.casefold() in missing_tokens else text)
    return cleaned

def coerce_numeric_column(self: object, records: list[dict[str, object]], column: str, invalid_value: float | None = None) -> list[dict[str, object]]:
    cleaned: list[dict[str, object]] = []
    for record in records:
        updated = record.copy()
        value = record.get(column)
        converted = invalid_value
        if isinstance(value, (str, int, float)) and not isinstance(value, bool):
            try:
                number = float(value)
            except (ValueError, TypeError, OverflowError):
                number = None
            if number is not None and math.isfinite(number):
                converted = number
        updated[column] = converted
        cleaned.append(updated)
    return cleaned

def impute_numeric_column(self: object, records: list[dict[str, object]], column: str, *, strategy: str = "median", constant: float | None = None) -> list[dict[str, object]]:
    if strategy not in {"mean", "median", "constant"}:
        raise ValueError("Strategy must be mean, median, or constant")
    observed: list[float] = []
    missing_positions: set[int] = set()
    for index, record in enumerate(records):
        value = record.get(column)
        if value is None or isinstance(value, float) and math.isnan(value):
            missing_positions.add(index)
            continue
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"Column {column!r} must contain numeric values")
        try:
            number = float(value)
        except OverflowError as exc:
            raise ValueError("Numeric value exceeds the supported range") from exc
        if not math.isfinite(number):
            raise ValueError("Observed numeric values must be finite")
        observed.append(number)
    if strategy == "constant":
        if isinstance(constant, bool) or not isinstance(constant, float):
            raise TypeError("Constant strategy requires a float constant")
        if not math.isfinite(constant):
            raise ValueError("The constant must be finite")
        replacement = constant
    else:
        if not observed:
            raise ValueError("Cannot estimate a replacement without observed values")
        replacement = statistics.mean(observed) if strategy == "mean" else statistics.median(observed)
        if not math.isfinite(replacement):
            raise ValueError("The estimated replacement must be finite")
    result: list[dict[str, object]] = []
    for index, record in enumerate(records):
        updated = record.copy()
        if index in missing_positions:
            updated[column] = replacement
        result.append(updated)
    return result

def prefix_medians(values: Iterable[float]) -> Iterator[float]:
    ordered: list[float] = []
    for value in values:
        bisect.insort(ordered, value)
        size = len(ordered)
        middle = size // 2
        if size % 2:
            yield float(ordered[middle])
        else:
            yield (ordered[middle - 1] + ordered[middle]) / 2

def moving_averages(values: Iterable[float], window: int = 7, min_samples: int = 1) -> Iterator[float]:
    if window < 1:
        raise ValueError('window must be positive')
    if not 1 <= min_samples <= window:
        raise ValueError('min_samples must be between one and window')
    recent: deque[float] = deque()
    for value in values:
        if not math.isfinite(value):
            raise ValueError('moving averages require finite values')
        recent.append(value)
        if len(recent) > window:
            recent.popleft()
        if len(recent) >= min_samples:
            yield sum(recent) / len(recent)

def histogram_updates(values: Iterable[float], bin_width: float = 1.0, origin: float = 0.0) -> Iterator[tuple[int, int]]:
    if not math.isfinite(bin_width) or bin_width <= 0:
        raise ValueError('bin_width must be finite and positive')
    if not math.isfinite(origin):
        raise ValueError('origin must be finite')
    counts: dict[int, int] = {}
    for value in values:
        if not math.isfinite(value):
            raise ValueError('histogram values must be finite')
        position = (value - origin) / bin_width
        if not math.isfinite(position):
            raise ValueError('value cannot be represented as a bin position')
        index = math.floor(position)
        counts[index] = counts.get(index, 0) + 1
        yield index, counts[index]

def rolling_percentiles(values: Iterable[float], *, percentile: float = 50.0, window: int = 20, min_samples: int = 1, method: str = 'linear') -> Iterator[float]:
    if not math.isfinite(percentile) or not 0 <= percentile <= 100:
        raise ValueError('percentile must be between zero and one hundred')
    if window < 1:
        raise ValueError('window must be positive')
    if not 1 <= min_samples <= window:
        raise ValueError('min_samples must be between one and window')
    if method not in ('linear', 'lower', 'higher'):
        raise ValueError('method must be linear, lower, or higher')
    recent: deque[float] = deque()
    for value in values:
        if not math.isfinite(value):
            raise ValueError('percentiles require finite values')
        recent.append(value)
        if len(recent) > window:
            recent.popleft()
        if len(recent) < min_samples:
            continue
        ordered = sorted(recent)
        position = (percentile / 100) * (len(ordered) - 1)
        lower = math.floor(position)
        upper = math.ceil(position)
        if method == 'lower':
            result = float(ordered[lower])
        elif method == 'higher':
            result = float(ordered[upper])
        elif lower == upper:
            result = float(ordered[lower])
        else:
            fraction = position - lower
            result = ordered[lower] * (1 - fraction) + ordered[upper] * fraction
        yield result

def robust_outlier_events(values: Iterable[float], *, history_size: int = 31, min_history: int = 5, threshold: float = 3.5, retain_outliers: bool = False) -> Iterator[tuple[int, float, float]]:
    if history_size < 1:
        raise ValueError('history_size must be positive')
    if not 1 <= min_history <= history_size:
        raise ValueError('min_history must be between one and history_size')
    if not math.isfinite(threshold) or threshold <= 0:
        raise ValueError('threshold must be finite and positive')
    history: deque[float] = deque(maxlen=history_size)
    for index, value in enumerate(values):
        if not math.isfinite(value):
            raise ValueError('outlier detection requires finite values')
        if len(history) < min_history:
            history.append(value)
            continue
        center = statistics.median(history)
        deviations = [abs(previous - center) for previous in history]
        deviation = statistics.median(deviations)
        difference = value - center
        if deviation == 0:
            if difference == 0:
                score = 0.0
            else:
                score = math.copysign(math.inf, difference)
        else:
            score = 0.6744897501960817 * difference / deviation
        is_outlier = abs(score) > threshold
        if not is_outlier or retain_outliers:
            history.append(value)
        if is_outlier:
            yield index, value, score

def fill_blank_text(values: Iterable[str | None], replacement: str = "") -> Iterator[str]:
    for value in values:
        if value is None or not value.strip():
            yield replacement
        else:
            yield value.strip()

def unique_text_values(values: Iterable[str], case_sensitive: bool = True) -> Iterator[str]:
    seen: set[str] = set()
    for value in values:
        cleaned = value.strip()
        key = cleaned if case_sensitive else cleaned.casefold()
        if key not in seen:
            seen.add(key)
            yield cleaned

def coerce_amount_column(records: Iterable[dict[str, object]], column: str, invalid_value: float | None = None) -> Iterator[dict[str, object]]:
    for record in records:
        cleaned = dict(record)
        raw = record.get(column)
        if isinstance(raw, str):
            raw = raw.strip().replace(",", "")
        if raw is None or isinstance(raw, bool) or raw == "":
            cleaned[column] = invalid_value
        else:
            try:
                amount = float(raw)
            except (TypeError, ValueError, OverflowError):
                cleaned[column] = invalid_value
            else:
                cleaned[column] = amount if math.isfinite(amount) else invalid_value
        yield cleaned

def deduplicate_recent_records(records: Iterable[dict[str, object]], fields: tuple[str, ...], *, capacity: int = 1000, missing: str = "error") -> Iterator[dict[str, object]]:
    if not fields:
        raise ValueError("At least one deduplication field is required")
    if isinstance(capacity, bool) or not isinstance(capacity, int):
        raise TypeError("Capacity must be an integer")
    if capacity < 1:
        raise ValueError("Capacity must be positive")
    if missing not in {"error", "skip", "keep"}:
        raise ValueError("Missing policy must be error, skip, or keep")
    recent: OrderedDict[tuple[object, ...], None] = OrderedDict()
    for record in records:
        absent = [field for field in fields if field not in record or record[field] is None]
        if absent:
            if missing == "error":
                raise KeyError(f"Missing deduplication fields: {', '.join(absent)}")
            if missing == "skip":
                continue
            yield dict(record)
            continue
        key = tuple(record[field] for field in fields)
        try:
            hash(key)
        except TypeError:
            raise TypeError("Deduplication field values must be hashable") from None
        if key in recent:
            recent.move_to_end(key)
            continue
        recent[key] = None
        if len(recent) > capacity:
            recent.popitem(last=False)
        yield dict(record)

def forward_fill_record_fields(records: Iterable[dict[str, object]], fields: tuple[str, ...], *, group_by: str | None = None, max_gap: int | None = None) -> Iterator[dict[str, object]]:
    if not fields or len(set(fields)) != len(fields):
        raise ValueError("Fields must be nonempty and unique")
    if group_by in fields:
        raise ValueError("The grouping column cannot be forward-filled")
    if max_gap is not None:
        if isinstance(max_gap, bool) or not isinstance(max_gap, int):
            raise TypeError("Maximum gap must be an integer or None")
        if max_gap < 0:
            raise ValueError("Maximum gap cannot be negative")
    previous: dict[str, object] = {}
    gaps: dict[str, int] = {}
    current_group: object = object()
    for record in records:
        if group_by is not None:
            if group_by not in record:
                raise KeyError(f"Missing grouping column: {group_by}")
            group = record[group_by]
            if group != current_group:
                previous.clear()
                gaps.clear()
                current_group = group
        cleaned = dict(record)
        for field in fields:
            value = record.get(field)
            is_missing = value is None or (isinstance(value, str) and not value.strip())
            if not is_missing:
                previous[field] = value
                gaps[field] = 0
            else:
                gaps[field] = gaps.get(field, 0) + 1
                within_limit = max_gap is None or gaps[field] <= max_gap
                if field in previous and within_limit:
                    cleaned[field] = previous[field]
                else:
                    cleaned[field] = None
        yield cleaned

async def deduplicate_records(records: list[dict[str, object]], key: str = "id", keep_last: bool = False) -> list[dict[str, object]]:
    await asyncio.sleep(0)
    seen: set[object] = set()
    result: list[dict[str, object]] = []
    ordered = reversed(records) if keep_last else iter(records)
    for record in ordered:
        if key not in record:
            raise KeyError(f"Record is missing deduplication key {key!r}")
        identity = record[key]
        try:
            hash(identity)
        except TypeError:
            raise TypeError(f"Deduplication key {key!r} must contain hashable values") from None
        if identity not in seen:
            seen.add(identity)
            result.append(record.copy())
    if keep_last:
        result.reverse()
    return result

async def remap_record_columns(records: list[dict[str, object]], mapping: dict[str, str], *, unmapped: str = "keep", collision: str = "raise") -> list[dict[str, object]]:
    if unmapped not in {"keep", "drop", "raise"}:
        raise ValueError("unmapped must be 'keep', 'drop', or 'raise'")
    if collision not in {"raise", "first", "last"}:
        raise ValueError("collision must be 'raise', 'first', or 'last'")
    for source, target in mapping.items():
        if not isinstance(source, str) or not isinstance(target, str):
            raise TypeError("Column mappings must have string keys and values")
        if not target.strip():
            raise ValueError("Target column names must not be blank")
    await asyncio.sleep(0)
    output: list[dict[str, object]] = []
    for index, record in enumerate(records):
        renamed: dict[str, object] = {}
        for source, value in record.items():
            if source in mapping:
                target = mapping[source]
            elif unmapped == "drop":
                continue
            elif unmapped == "raise":
                raise KeyError(f"Unmapped column {source!r} in row {index}")
            else:
                target = source
            if target in renamed:
                if collision == "raise":
                    raise ValueError(f"Multiple columns map to {target!r} in row {index}")
                if collision == "first":
                    continue
            renamed[target] = value
        output.append(renamed)
    return output

async def merge_duplicate_records(records: list[dict[str, object]], *, id_column: str = "id", conflict: str = "raise", blank_is_missing: bool = True) -> list[dict[str, object]]:
    if conflict not in {"raise", "first", "last"}:
        raise ValueError("conflict must be 'raise', 'first', or 'last'")
    merged: dict[object, dict[str, object]] = {}
    for index, record in enumerate(records):
        await asyncio.sleep(0)
        if id_column not in record:
            raise KeyError(f"Row {index} is missing identity column {id_column!r}")
        identity = record[id_column]
        if identity is None or isinstance(identity, str) and not identity.strip():
            raise ValueError(f"Row {index} has a missing identity")
        try:
            hash(identity)
        except TypeError:
            raise TypeError(f"Identity in row {index} must be hashable") from None
        if identity not in merged:
            merged[identity] = record.copy()
            continue
        target = merged[identity]
        for column, incoming in record.items():
            if column == id_column:
                continue
            incoming_missing = incoming is None or blank_is_missing and isinstance(incoming, str) and not incoming.strip()
            if column not in target:
                target[column] = incoming
                continue
            current = target[column]
            current_missing = current is None or blank_is_missing and isinstance(current, str) and not current.strip()
            if incoming_missing:
                continue
            if current_missing:
                target[column] = incoming
            elif current != incoming:
                if conflict == "raise":
                    raise ValueError(f"Conflicting values for identity {identity!r}, column {column!r}")
                if conflict == "last":
                    target[column] = incoming
    return list(merged.values())

def http_status_class(status_code: int) -> str:
    if not 100 <= status_code <= 599:
        raise ValueError("HTTP status code must be between 100 and 599")
    classes = ("informational", "success", "redirection", "client error", "server error")
    index = status_code // 100 - 1
    return classes[index]

def find_http_header(headers: dict[str, str], name: str) -> str | None:
    normalized_name = name.lower()
    for header_name, value in headers.items():
        if header_name.lower() == normalized_name:
            return value
    return None

def update_url_query(url: str, updates: dict[str, str | None], sort_keys: bool = False) -> str:
    parts = urlsplit(url)
    original_pairs = parse_qsl(parts.query, keep_blank_values=True)
    pairs: list[tuple[str, str]] = []
    for key, value in original_pairs:
        if key not in updates:
            pairs.append((key, value))
    for key, value in updates.items():
        if value is not None:
            pairs.append((key, value))
    if sort_keys:
        pairs.sort(key=lambda pair: pair[0])
    query = urlencode(pairs)
    return urlunsplit((parts.scheme, parts.netloc, parts.path, query, parts.fragment))

def http_retry_delay(attempt: int, initial_delay: float = 0.5, max_delay: float = 60.0, retry_after: float | None = None) -> float:
    if attempt < 0:
        raise ValueError("Retry attempt must be nonnegative")
    if not math.isfinite(initial_delay) or initial_delay <= 0:
        raise ValueError("Initial delay must be finite and positive")
    if not math.isfinite(max_delay) or max_delay < 0:
        raise ValueError("Maximum delay must be finite and nonnegative")
    if retry_after is not None:
        if not math.isfinite(retry_after) or retry_after < 0:
            raise ValueError("Retry-After delay must be finite and nonnegative")
    try:
        delay = math.ldexp(initial_delay, attempt)
    except OverflowError:
        delay = max_delay
    delay = min(delay, max_delay)
    if retry_after is not None:
        delay = max(delay, retry_after)
    return float(delay)

def next_pagination_url(link_header: str, base_url: str, *, allow_cross_origin: bool = False) -> str | None:
    base = urlsplit(base_url)
    if base.scheme not in {"http", "https"} or not base.hostname:
        raise ValueError("Base URL must be an absolute HTTP or HTTPS URL")
    base_port = base.port if base.port is not None else (443 if base.scheme == "https" else 80)
    base_origin = (base.scheme, base.hostname, base_port)
    for entry in re.split(r',(?=\s*<)', link_header):
        if not entry.strip():
            continue
        match = re.fullmatch(r'\s*<([^>]+)>(.*)', entry)
        if match is None:
            raise ValueError("Malformed pagination Link header entry")
        attributes = match.group(2)
        relation = re.search(r'(?:^|;)\s*rel\s*=\s*(?:"([^"]*)"|([^;\s]+))', attributes, re.IGNORECASE)
        if relation is None:
            continue
        relations = (relation.group(1) or relation.group(2) or "").split()
        if "next" not in relations:
            continue
        resolved = urljoin(base_url, match.group(1))
        target = urlsplit(resolved)
        if target.scheme not in {"http", "https"} or not target.hostname:
            raise ValueError("Pagination link must resolve to an HTTP or HTTPS URL")
        if target.username is not None or target.password is not None:
            raise ValueError("Pagination URL must not contain credentials")
        target_port = target.port if target.port is not None else (443 if target.scheme == "https" else 80)
        target_origin = (target.scheme, target.hostname, target_port)
        if not allow_cross_origin and target_origin != base_origin:
            raise ValueError("Cross-origin pagination link is not permitted")
        return urlunsplit((target.scheme, target.netloc, target.path, target.query, ""))
    return None

def rate_limit_wait(headers: dict[str, str], *, now: datetime | None = None, max_wait: float = 300.0) -> float:
    if not math.isfinite(max_wait) or max_wait < 0:
        raise ValueError("Maximum wait must be finite and nonnegative")
    current = now if now is not None else datetime.now(timezone.utc)
    if current.tzinfo is None or current.utcoffset() is None:
        raise ValueError("Current time must be timezone-aware")
    normalized = {key.lower(): value.strip() for key, value in headers.items()}
    wait = 0.0
    retry_after = normalized.get("retry-after")
    if retry_after is not None:
        if re.fullmatch(r'[0-9]+', retry_after):
            wait = float(min(int(retry_after), max_wait))
        else:
            try:
                deadline = parsedate_to_datetime(retry_after)
            except (TypeError, ValueError, OverflowError) as error:
                raise ValueError("Retry-After must contain seconds or an HTTP date") from error
            if deadline is None:
                raise ValueError("Retry-After contains an invalid HTTP date")
            if deadline.tzinfo is None:
                deadline = deadline.replace(tzinfo=timezone.utc)
            wait = max(0.0, (deadline - current).total_seconds())
    remaining = normalized.get("x-ratelimit-remaining")
    if remaining is not None:
        try:
            remaining_count = int(remaining)
        except ValueError as error:
            raise ValueError("Rate-limit remaining count must be an integer") from error
        if remaining_count < 0:
            raise ValueError("Rate-limit remaining count must be nonnegative")
        if remaining_count == 0 and "x-ratelimit-reset" in normalized:
            try:
                reset = float(normalized["x-ratelimit-reset"])
            except ValueError as error:
                raise ValueError("Rate-limit reset must be a Unix timestamp") from error
            if not math.isfinite(reset):
                raise ValueError("Rate-limit reset timestamp must be finite")
            wait = max(wait, reset - current.timestamp(), 0.0)
    return float(min(wait, max_wait))

def get_header(self: "HttpClient", name: str) -> str | None:
    target = name.strip().casefold()
    for key, value in self.headers.items():
        if key.casefold() == target:
            return value
    return None

def is_success_status(self: "HttpClient", status: int) -> bool:
    if not 100 <= status <= 599:
        raise ValueError("HTTP status must be between 100 and 599")
    successful = 200 <= status < 300
    return successful

def build_url(self: "HttpClient", path: str, query: dict[str, str | list[str] | None] | None = None) -> str:
    absolute = urljoin(self.base_url, path)
    parts = urlsplit(absolute)
    if parts.scheme not in {"http", "https"} or not parts.netloc:
        raise ValueError("URL must use HTTP or HTTPS and include a host")
    pairs = parse_qsl(parts.query, keep_blank_values=True)
    if query is not None:
        replaced = set(query)
        pairs = [(key, value) for key, value in pairs if key not in replaced]
        for key, value in query.items():
            if value is None:
                continue
            values = value if isinstance(value, list) else [value]
            pairs.extend((key, item) for item in values)
    encoded = urlencode(pairs)
    return urlunsplit((parts.scheme, parts.netloc, parts.path, encoded, parts.fragment))

def prepare_headers(self: "HttpClient", overrides: dict[str, str | None], include_defaults: bool = True) -> dict[str, str]:
    result: dict[str, str] = {}
    names: dict[str, str] = {}
    sources = [self.headers, overrides] if include_defaults else [overrides]
    for source in sources:
        for name, value in source.items():
            if not re.fullmatch(r"[!#$%&'*+.^_`|~0-9A-Za-z-]+", name):
                raise ValueError("Invalid HTTP header name")
            if value is not None and ("\r" in value or "\n" in value):
                raise ValueError("HTTP header values cannot contain line breaks")
            normalized = name.casefold()
            previous = names.pop(normalized, None)
            if previous is not None:
                del result[previous]
            if value is not None:
                names[normalized] = name
                result[name] = value
    return result

def iter_url_query_pairs(url: str, keep_blank_values: bool = True) -> Iterator[tuple[str, str]]:
    query = urlsplit(url).query
    pairs = parse_qsl(query, keep_blank_values=keep_blank_values)
    for name, value in pairs:
        yield name, value

def iter_header_values(headers: Iterable[tuple[str, str]], name: str) -> Iterator[str]:
    target = name.casefold()
    for header_name, value in headers:
        normalized_name = header_name.casefold()
        if normalized_name == target:
            yield value.strip()

def iter_retry_delays(statuses: Iterable[int], initial_delay: float = 0.5, maximum_delay: float = 30.0) -> Iterator[float]:
    if not math.isfinite(initial_delay) or initial_delay < 0:
        raise ValueError('Initial delay must be finite and nonnegative')
    if not math.isfinite(maximum_delay) or maximum_delay < initial_delay:
        raise ValueError('Maximum delay must be finite and at least the initial delay')
    delay = initial_delay
    retryable = {429, 500, 502, 503, 504}
    for status in statuses:
        if not 100 <= status <= 599:
            raise ValueError('HTTP status must be between 100 and 599')
        if status in retryable:
            yield delay
            delay = min(maximum_delay, delay * 2)
        else:
            delay = initial_delay

def iter_numbered_page_urls(base_url: str, total_pages: int, page_parameter: str = 'page') -> Iterator[str]:
    if total_pages < 0:
        raise ValueError('Total pages cannot be negative')
    if not page_parameter:
        raise ValueError('Page parameter cannot be empty')
    parts = urlsplit(base_url)
    if parts.scheme not in {'http', 'https'} or not parts.hostname:
        raise ValueError('Base URL must be an absolute HTTP or HTTPS URL')
    existing = parse_qsl(parts.query, keep_blank_values=True)
    retained = [(key, value) for key, value in existing if key != page_parameter]
    for page_number in range(1, total_pages + 1):
        parameters = retained + [(page_parameter, str(page_number))]
        query = urlencode(parameters)
        yield urlunsplit((parts.scheme, parts.netloc, parts.path, query, parts.fragment))

def iter_paginated_items(start_url: str, fetch_page: Callable[[str], dict[str, Any]], *, max_pages: int = 100, same_origin: bool = True) -> Iterator[Any]:
    if max_pages < 1:
        raise ValueError('Maximum pages must be positive')
    initial = urlsplit(start_url)
    if initial.scheme not in {'http', 'https'} or not initial.hostname:
        raise ValueError('Starting URL must be an absolute HTTP or HTTPS URL')
    initial_origin = (initial.scheme, initial.hostname, initial.port or (443 if initial.scheme == 'https' else 80))
    current = urlunsplit(initial._replace(fragment=''))
    visited: set[str] = set()
    for page_number in range(max_pages):
        parts = urlsplit(current)
        if parts.scheme not in {'http', 'https'} or not parts.hostname:
            raise ValueError('Pagination link must resolve to an HTTP or HTTPS URL')
        origin = (parts.scheme, parts.hostname, parts.port or (443 if parts.scheme == 'https' else 80))
        if same_origin and origin != initial_origin:
            raise ValueError('Pagination link changed the URL origin')
        if current in visited:
            raise ValueError('Pagination link formed a cycle')
        visited.add(current)
        page = fetch_page(current)
        if not isinstance(page, dict):
            raise TypeError('Fetched page must be a dictionary')
        if 'items' not in page:
            raise KeyError('Fetched page is missing items')
        items = page['items']
        if not isinstance(items, list):
            raise TypeError('Page items must be a list')
        next_link = page.get('next')
        if next_link is not None and not isinstance(next_link, str):
            raise TypeError('Next link must be a string or None')
        yield from items
        if not next_link:
            return
        if page_number + 1 == max_pages:
            raise ValueError('Pagination exceeded the maximum page count')
        resolved = urlsplit(urljoin(current, next_link))
        current = urlunsplit(resolved._replace(fragment=''))

def iter_rate_limit_waits(header_sets: Iterable[Mapping[str, str]], *, now: datetime | None = None, maximum_wait: float = 300.0) -> Iterator[float]:
    if not math.isfinite(maximum_wait) or maximum_wait < 0:
        raise ValueError('Maximum wait must be finite and nonnegative')
    reference = datetime.now(timezone.utc) if now is None else now
    if reference.utcoffset() is None:
        raise ValueError('Reference time must be timezone-aware')
    reference_timestamp = reference.timestamp()
    for headers in header_sets:
        normalized = {name.casefold(): value.strip() for name, value in headers.items()}
        retry_after = normalized.get('retry-after')
        if retry_after is not None:
            if retry_after.isascii() and retry_after.isdigit():
                wait = min(int(retry_after), maximum_wait)
            else:
                try:
                    deadline = parsedate_to_datetime(retry_after)
                except (ValueError, TypeError, OverflowError) as error:
                    raise ValueError('Retry-After must contain seconds or an HTTP date') from error
                if deadline.utcoffset() is None:
                    deadline = deadline.replace(tzinfo=timezone.utc)
                wait = deadline.timestamp() - reference_timestamp
        elif normalized.get('x-ratelimit-remaining') == '0':
            reset = normalized.get('x-ratelimit-reset')
            if reset is None:
                raise KeyError('Exhausted rate limit is missing X-RateLimit-Reset')
            try:
                reset_timestamp = float(reset)
            except ValueError as error:
                raise ValueError('X-RateLimit-Reset must be a Unix timestamp') from error
            if not math.isfinite(reset_timestamp):
                raise ValueError('Rate-limit reset timestamp must be finite')
            wait = reset_timestamp - reference_timestamp
        else:
            wait = 0.0
        yield min(maximum_wait, max(0.0, wait))

async def get_with_backoff(client: Any, url: str, attempts: int = 3, initial_delay: float = 0.5) -> Any:
    if attempts < 1:
        raise ValueError("Attempts must be at least one")
    if not math.isfinite(initial_delay) or initial_delay < 0:
        raise ValueError("Initial delay must be finite and nonnegative")
    delay = initial_delay
    for attempt in range(attempts):
        response = await client.get(url)
        if response.status_code not in {429, 502, 503, 504}:
            response.raise_for_status()
            return response
        if attempt + 1 == attempts:
            raise TimeoutError(f"Retry budget exhausted after HTTP {response.status_code}")
        await asyncio.sleep(delay)
        delay = min(delay * 2, 60.0)
    raise TimeoutError("No request completed")

def is_python_identifier(candidate: str, max_length: int = 64) -> bool:
    if max_length < 1 or not candidate:
        return False
    if len(candidate) > max_length:
        return False
    return candidate.isidentifier() and not keyword.iskeyword(candidate)

def is_within_numeric_range(value: float, bounds: tuple[float, float]) -> bool:
    lower, upper = bounds
    if lower > upper:
        return False
    if isinstance(value, bool) or not math.isfinite(value):
        return False
    return lower <= value <= upper

def normalize_email_address(address: str, allow_local_domain: bool = False) -> str | None:
    candidate = address.strip()
    if len(candidate) > 254 or candidate.count('@') != 1:
        return None
    local, domain = candidate.split('@')
    if not local or len(local) > 64:
        return None
    if not re.fullmatch(r"[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+", local):
        return None
    if local.startswith('.') or local.endswith('.') or '..' in local:
        return None
    try:
        domain = domain.encode('idna').decode('ascii').lower()
    except UnicodeError:
        return None
    labels = domain.split('.')
    if not allow_local_domain and len(labels) < 2:
        return None
    for label in labels:
        if not re.fullmatch(r'[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?', label):
            return None
    normalized = f'{local}@{domain}'
    return normalized if len(normalized) <= 254 else None

def password_policy_errors(password: str, min_length: int = 12, required_classes: int = 3) -> list[str]:
    if min_length < 1:
        raise ValueError('Minimum password length must be positive')
    if not 0 <= required_classes <= 4:
        raise ValueError('Required character classes must be between zero and four')
    errors: list[str] = []
    if len(password) < min_length:
        errors.append(f'Password must contain at least {min_length} characters')
    classes = (
        any(character.islower() for character in password),
        any(character.isupper() for character in password),
        any(character.isdecimal() for character in password),
        any(not character.isalnum() and not character.isspace() for character in password),
    )
    if sum(classes) < required_classes:
        errors.append(f'Password must use at least {required_classes} character classes')
    if any(character.isspace() for character in password):
        errors.append('Password must not contain whitespace')
    if any(unicodedata.category(character).startswith('C') for character in password):
        errors.append('Password must not contain control or formatting characters')
    return errors

def validate_record_schema(record: dict[str, object], schema: dict[str, type], *, required: tuple[str, ...] = (), nullable: tuple[str, ...] = (), allow_extra: bool = False) -> dict[str, object]:
    if not isinstance(record, dict) or not isinstance(schema, dict):
        raise TypeError('Record and schema must be dictionaries')
    for field, expected_type in schema.items():
        if not isinstance(field, str) or not field:
            raise ValueError('Schema field names must be nonempty strings')
        if not isinstance(expected_type, type):
            raise TypeError(f'Schema type for {field!r} must be a class')
    for field in required:
        if field not in schema:
            raise ValueError(f'Required field {field!r} is not defined in the schema')
    for field in nullable:
        if field not in schema:
            raise ValueError(f'Nullable field {field!r} is not defined in the schema')
    for field in required:
        if field not in record:
            raise KeyError(f'Missing required field {field!r}')
    validated: dict[str, object] = {}
    for field, value in record.items():
        if not isinstance(field, str):
            raise TypeError('Record field names must be strings')
        if field not in schema:
            if not allow_extra:
                raise ValueError(f'Unexpected field {field!r}')
            validated[field] = value
            continue
        expected_type = schema[field]
        if value is None and field in nullable:
            validated[field] = None
            continue
        if expected_type in (int, float) and isinstance(value, bool):
            raise TypeError(f'Field {field!r} must not be a boolean')
        if not isinstance(value, expected_type):
            raise TypeError(f'Field {field!r} must be an instance of {expected_type.__name__}')
        validated[field] = value
    return validated

def parse_integer_selection(text: str, *, minimum: int = 1, maximum: int = 1000, allow_duplicates: bool = False, max_items: int = 100) -> list[int]:
    if isinstance(minimum, bool) or not isinstance(minimum, int):
        raise TypeError('Minimum must be an integer')
    if isinstance(maximum, bool) or not isinstance(maximum, int):
        raise TypeError('Maximum must be an integer')
    if minimum > maximum:
        raise ValueError('Minimum must not exceed maximum')
    if isinstance(max_items, bool) or not isinstance(max_items, int):
        raise TypeError('Item limit must be an integer')
    if max_items < 1:
        raise ValueError('Item limit must be positive')
    if not isinstance(text, str):
        raise TypeError('Selection must be a string')
    if not text.strip():
        raise ValueError('Selection must not be empty')
    tokens = text.split(',')
    if len(tokens) > max_items:
        raise ValueError(f'Selection must contain at most {max_items} items')
    values: list[int] = []
    seen: set[int] = set()
    for position, token in enumerate(tokens, start=1):
        token = token.strip()
        if not token:
            raise ValueError(f'Item {position} is empty')
        if not re.fullmatch(r'[+-]?[0-9]+', token):
            raise ValueError(f'Item {position} is not a decimal integer')
        value = int(token)
        if not minimum <= value <= maximum:
            raise ValueError(f'Item {position} must be between {minimum} and {maximum}')
        if value in seen and not allow_duplicates:
            raise ValueError(f'Duplicate selection value {value}')
        seen.add(value)
        values.append(value)
    return values

def is_valid_email(self: object, address: str) -> bool:
    if not isinstance(address, str) or len(address) > 254:
        return False
    if address.count('@') != 1:
        return False
    local, domain = address.split('@')
    if len(local) > 64 or local.startswith('.') or local.endswith('.') or '..' in local:
        return False
    pattern = r"[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}"
    return re.fullmatch(pattern, address) is not None

def is_valid_account_id(self: object, identifier: str) -> bool:
    if not isinstance(identifier, str):
        return False
    if not 3 <= len(identifier) <= 32:
        return False
    return re.fullmatch(r'[A-Za-z][A-Za-z0-9_]*', identifier) is not None

def password_issues(self: object, password: str, minimum_length: int = 12, require_symbol: bool = True) -> list[str]:
    if not isinstance(password, str):
        raise TypeError('Password must be a string')
    if isinstance(minimum_length, bool) or not isinstance(minimum_length, int):
        raise TypeError('Minimum length must be an integer')
    if minimum_length < 1:
        raise ValueError('Minimum length must be positive')
    issues: list[str] = []
    if len(password) < minimum_length:
        issues.append('too_short')
    if not any(character.islower() for character in password):
        issues.append('missing_lowercase')
    if not any(character.isupper() for character in password):
        issues.append('missing_uppercase')
    if not any(character.isdecimal() for character in password):
        issues.append('missing_digit')
    if require_symbol and not any(not character.isalnum() and not character.isspace() for character in password):
        issues.append('missing_symbol')
    if any(character.isspace() for character in password):
        issues.append('contains_whitespace')
    return issues

def score_in_range(self: object, score: float, bounds: tuple[float, float] = (0.0, 100.0)) -> bool:
    if len(bounds) != 2:
        raise ValueError('Bounds must contain exactly two endpoints')
    lower, upper = bounds
    if any(isinstance(endpoint, bool) or not isinstance(endpoint, (int, float)) for endpoint in bounds):
        raise TypeError('Range endpoints must be numeric')
    if any(endpoint != endpoint or endpoint in (float('inf'), float('-inf')) for endpoint in bounds):
        raise ValueError('Range endpoints must be finite')
    if lower > upper:
        raise ValueError('Lower endpoint cannot exceed upper endpoint')
    if isinstance(score, bool) or not isinstance(score, (int, float)):
        return False
    return lower <= score <= upper

def validate_record(self: object, payload: dict[str, object], schema: dict[str, type], *, required: tuple[str, ...] = (), allow_extra: bool = False) -> dict[str, object]:
    if not isinstance(payload, dict) or not isinstance(schema, dict):
        raise TypeError('Payload and schema must be dictionaries')
    for field, expected_type in schema.items():
        if not isinstance(field, str):
            raise TypeError('Schema field names must be strings')
        if not isinstance(expected_type, type):
            raise TypeError(f'Schema entry for {field!r} must be a type')
    for field in required:
        if not isinstance(field, str):
            raise TypeError('Required field names must be strings')
        if field not in schema:
            raise ValueError(f'Required field {field!r} is not defined in the schema')
    for field in payload:
        if not isinstance(field, str):
            raise TypeError('Payload field names must be strings')
        if field not in schema and not allow_extra:
            raise ValueError(f'Unexpected field {field!r}')
    for field in required:
        if field not in payload:
            raise KeyError(f'Missing required field {field!r}')
    validated: dict[str, object] = {}
    for field, value in payload.items():
        if field in schema:
            expected_type = schema[field]
            if expected_type in (int, float) and isinstance(value, bool):
                raise TypeError(f'Field {field!r} cannot be a boolean')
            if not isinstance(value, expected_type):
                raise TypeError(f'Field {field!r} must be an instance of {expected_type.__name__}')
        validated[field] = value
    return validated

def parse_option_selection(self: object, text: str, *, maximum_option: int, selection_limit: int = 20) -> list[int]:
    if not isinstance(text, str):
        raise TypeError('Selection must be a string')
    for value in (maximum_option, selection_limit):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError('Option and selection limits must be integers')
        if value < 1:
            raise ValueError('Option and selection limits must be positive')
    if not text.strip():
        raise ValueError('Select at least one option')
    selected: list[int] = []
    seen: set[int] = set()
    for token in text.split(','):
        token = token.strip()
        if not token:
            raise ValueError('Selection contains an empty item')
        match = re.fullmatch(r'([0-9]+)(?:\s*-\s*([0-9]+))?', token)
        if match is None:
            raise ValueError(f'Invalid selection item {token!r}')
        start = int(match.group(1))
        end_text = match.group(2)
        end = start if end_text is None else int(end_text)
        if start > end:
            raise ValueError(f'Reversed range {token!r}')
        if start < 1 or end > maximum_option:
            raise ValueError(f'Selection must stay between 1 and {maximum_option}')
        if len(selected) + end - start + 1 > selection_limit:
            raise ValueError(f'At most {selection_limit} options may be selected')
        for option in range(start, end + 1):
            if option in seen:
                raise ValueError(f'Option {option} was selected more than once')
            seen.add(option)
            selected.append(option)
    return selected

def find_malformed_email_addresses(addresses: list[str]) -> Iterator[str]:
    pattern = r"[^\s@]+@[^\s@.]+(?:\.[^\s@.]+)+"
    for address in addresses:
        candidate = address.strip()
        if re.fullmatch(pattern, candidate) is None:
            yield address

def find_out_of_range_readings(readings: list[float], bounds: tuple[float, float]) -> Iterator[int]:
    lower, upper = bounds
    if not math.isfinite(lower) or not math.isfinite(upper) or lower > upper:
        raise ValueError("Bounds must be finite and ordered from lowest to highest")
    for index, reading in enumerate(readings):
        if not math.isfinite(reading) or not lower <= reading <= upper:
            yield index

def password_policy_violations(password: str, minimum_length: int = 12, require_symbol: bool = True) -> Iterator[str]:
    if minimum_length < 1:
        raise ValueError("Minimum password length must be positive")
    if len(password) < minimum_length:
        yield f"Password must contain at least {minimum_length} characters"
    if not any(character.islower() for character in password):
        yield "Password must contain a lowercase letter"
    if not any(character.isupper() for character in password):
        yield "Password must contain an uppercase letter"
    if not any(character.isdigit() for character in password):
        yield "Password must contain a digit"
    if require_symbol and not any(not character.isalnum() and not character.isspace() for character in password):
        yield "Password must contain a symbol"
    if any(character.isspace() for character in password):
        yield "Password must not contain whitespace"

def identifier_batch_errors(names: Iterable[str], maximum_length: int = 64, reserved_names: tuple[str, ...] = ()) -> Iterator[tuple[int, str]]:
    if maximum_length < 1:
        raise ValueError("Maximum identifier length must be positive")
    reserved = set(reserved_names)
    seen: set[str] = set()
    for index, name in enumerate(names):
        if not name:
            yield index, "Identifier must not be empty"
        else:
            if len(name) > maximum_length:
                yield index, f"Identifier exceeds {maximum_length} characters"
            if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name) is None:
                yield index, "Identifier must use ASCII letters, digits, and underscores and cannot start with a digit"
            if name in reserved:
                yield index, "Identifier is reserved"
            if name in seen:
                yield index, "Identifier duplicates an earlier entry"
        seen.add(name)

def record_schema_errors(records: Iterable[object], field_types: dict[str, type | tuple[type, ...]], *, required_fields: tuple[str, ...] = (), allow_extra_fields: bool = False) -> Iterator[tuple[int, str, str]]:
    for field, expected in field_types.items():
        if not isinstance(field, str):
            raise TypeError("Schema field names must be strings")
        if isinstance(expected, tuple):
            if not expected or not all(isinstance(item, type) for item in expected):
                raise TypeError(f"Schema types for {field!r} must be a nonempty tuple of types")
        elif not isinstance(expected, type):
            raise TypeError(f"Schema type for {field!r} must be a type or tuple of types")
    for field in required_fields:
        if not isinstance(field, str):
            raise TypeError("Required field names must be strings")
        if field not in field_types:
            raise ValueError(f"Required field {field!r} is not defined in the schema")
    required = set(required_fields)
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            yield index, "", "Record must be a dictionary"
            continue
        for field in field_types:
            if field not in record:
                if field in required:
                    yield index, field, "Required field is missing"
                continue
            expected = field_types[field]
            if not isinstance(record[field], expected):
                types = expected if isinstance(expected, tuple) else (expected,)
                description = ", ".join(item.__name__ for item in types)
                yield index, field, f"Expected an instance of: {description}"
        if not allow_extra_fields:
            for field in record:
                if field not in field_types:
                    yield index, str(field), "Field is not defined in the schema"

def numeric_input_errors(values: Iterable[object], *, minimum: float | None = None, maximum: float | None = None, allow_blank: bool = False, integer_only: bool = False) -> Iterator[tuple[int, str]]:
    if minimum is not None and not math.isfinite(minimum):
        raise ValueError("Minimum must be finite")
    if maximum is not None and not math.isfinite(maximum):
        raise ValueError("Maximum must be finite")
    if minimum is not None and maximum is not None and minimum > maximum:
        raise ValueError("Minimum must not exceed maximum")
    for index, raw in enumerate(values):
        if not isinstance(raw, str):
            yield index, "Input must be text"
            continue
        text = raw.strip()
        if not text:
            if not allow_blank:
                yield index, "A numeric value is required"
            continue
        try:
            number = float(text)
        except (ValueError, OverflowError):
            yield index, "Input is not a supported number"
            continue
        if not math.isfinite(number):
            yield index, "Number must be finite"
            continue
        if integer_only and not number.is_integer():
            yield index, "Number must be an integer"
        if minimum is not None and number < minimum:
            yield index, f"Number must be at least {minimum}"
        if maximum is not None and number > maximum:
            yield index, f"Number must be at most {maximum}"

async def check_password_policy(password: str, minimum_length: int = 12, forbidden_terms: tuple[str, ...] = ()) -> list[str]:
    if minimum_length < 1:
        raise ValueError("Minimum password length must be positive")
    await asyncio.sleep(0)
    failures = []
    if len(password) < minimum_length:
        failures.append("Password is too short")
    if not any(character.isupper() for character in password):
        failures.append("Password needs an uppercase letter")
    if not any(character.islower() for character in password):
        failures.append("Password needs a lowercase letter")
    if not any(character.isdigit() for character in password):
        failures.append("Password needs a digit")
    if not any(not character.isalnum() and not character.isspace() for character in password):
        failures.append("Password needs a symbol")
    if any(character.isspace() for character in password):
        failures.append("Password cannot contain whitespace")
    if any(term and term.casefold() in password.casefold() for term in forbidden_terms):
        failures.append("Password contains a forbidden term")
    return failures

async def validate_record_fields(record: dict[str, object], field_types: dict[str, type[object]], allow_extra: bool = False) -> list[str]:
    await asyncio.sleep(0)
    errors = []
    for field, expected_type in field_types.items():
        if not isinstance(expected_type, type):
            raise TypeError(f"Schema entry for {field!r} must be a type")
        if field not in record:
            errors.append(f"Missing required field: {field}")
        elif not isinstance(record[field], expected_type):
            errors.append(f"Field {field} must be of type {expected_type.__name__}")
        elif expected_type is int and isinstance(record[field], bool):
            errors.append(f"Field {field} must be an integer, not a boolean")
    if not allow_extra:
        for field in record:
            if field not in field_types:
                errors.append(f"Unexpected field: {field}")
    return errors

async def validate_available_username(username: str, client: Any, *, reserved: tuple[str, ...] = ("admin", "support", "root"), timeout: float = 3.0) -> str:
    if not math.isfinite(timeout) or timeout <= 0:
        raise ValueError("Availability timeout must be finite and positive")
    candidate = username.strip().lower()
    if not 3 <= len(candidate) <= 30:
        raise ValueError("Username must contain between 3 and 30 characters")
    if re.fullmatch(r"[a-z][a-z0-9_]*", candidate) is None:
        raise ValueError("Username must start with a letter and use ASCII letters, digits, or underscores")
    if candidate.endswith("_"):
        raise ValueError("Username cannot end with an underscore")
    if "__" in candidate:
        raise ValueError("Username cannot contain consecutive underscores")
    if candidate in {name.strip().lower() for name in reserved}:
        raise ValueError("Username is reserved")
    try:
        available = await asyncio.wait_for(client.is_username_available(candidate), timeout=timeout)
    except TimeoutError as exc:
        raise TimeoutError("Username availability check timed out") from exc
    if not isinstance(available, bool):
        raise TypeError("Availability service must return a boolean")
    if not available:
        raise ValueError("Username is already in use")
    return candidate

async def validate_transfer_amount(text: str, client: Any, *, currency: str, timeout: float = 5.0) -> Decimal:
    code = currency.strip().upper()
    if re.fullmatch(r"[A-Z]{3}", code) is None:
        raise ValueError("Currency must be a three-letter ASCII code")
    if not math.isfinite(timeout) or timeout <= 0:
        raise ValueError("Limit lookup timeout must be finite and positive")
    candidate = text.strip()
    if not candidate:
        raise ValueError("Transfer amount is required")
    pattern = r"[+-]?(?:[0-9]+|[0-9]{1,3}(?:,[0-9]{3})+)(?:\.[0-9]{1,2})?"
    if re.fullmatch(pattern, candidate) is None:
        raise ValueError("Amount must use valid comma grouping and at most two decimal places")
    amount = Decimal(candidate.replace(",", ""))
    if amount <= 0:
        raise ValueError("Transfer amount must be positive")
    try:
        raw_limit = await asyncio.wait_for(client.get_remaining_transfer_limit(code), timeout=timeout)
    except TimeoutError as exc:
        raise TimeoutError("Transfer limit lookup timed out") from exc
    if raw_limit is None:
        raise ValueError(f"Transfers are not supported for {code}")
    if isinstance(raw_limit, bool):
        raise TypeError("Transfer limit cannot be a boolean")
    try:
        limit = Decimal(str(raw_limit))
    except (InvalidOperation, ValueError) as exc:
        raise ValueError("Transfer service returned an invalid limit") from exc
    if not limit.is_finite() or limit < 0:
        raise ValueError("Transfer limit must be finite and nonnegative")
    if limit == 0:
        raise ValueError("No transfer allowance remains")
    if amount > limit:
        raise ValueError("Transfer amount exceeds the remaining allowance")
    return amount

def chunk_order_ids(order_ids: list[str], chunk_size: int) -> list[list[str]]:
    if chunk_size <= 0:
        raise ValueError("chunk_size must be positive")
    chunks: list[list[str]] = []
    for start in range(0, len(order_ids), chunk_size):
        chunks.append(order_ids[start:start + chunk_size])
    return chunks

def group_products_by_category(products: list[tuple[str, str]]) -> dict[str, list[str]]:
    grouped: dict[str, list[str]] = {}
    for product_id, category in products:
        if category not in grouped:
            grouped[category] = []
        grouped[category].append(product_id)
    return grouped

def merge_settings(base: dict[str, object], updates: dict[str, object], conflict: str = "overwrite") -> dict[str, object]:
    if conflict not in {"overwrite", "keep", "error"}:
        raise ValueError("conflict must be overwrite, keep, or error")
    merged = base.copy()
    for key, value in updates.items():
        if key not in merged:
            merged[key] = value
            continue
        if conflict == "keep":
            continue
        if conflict == "error":
            raise KeyError(f"Setting already exists: {key}")
        merged[key] = value
    return merged

def flatten_event_batches(batches: list[list[str]], unique: bool = False, limit: int | None = None) -> list[str]:
    if limit is not None and limit < 0:
        raise ValueError("limit must be nonnegative")
    flattened: list[str] = []
    seen: set[str] = set()
    if limit == 0:
        return flattened
    for batch in batches:
        for event_id in batch:
            if unique and event_id in seen:
                continue
            flattened.append(event_id)
            if unique:
                seen.add(event_id)
            if limit is not None and len(flattened) >= limit:
                return flattened
    return flattened

def sort_report_rows(rows: list[dict[str, object]], fields: tuple[str, ...], *, descending: tuple[str, ...] = (), missing: str = "last", limit: int | None = None) -> list[dict[str, object]]:
    if not fields:
        raise ValueError("At least one sort field is required")
    if len(set(fields)) != len(fields):
        raise ValueError("Sort fields must be unique")
    if not set(descending).issubset(fields):
        raise ValueError("Descending fields must appear in fields")
    if missing not in {"first", "last", "error"}:
        raise ValueError("missing must be first, last, or error")
    if limit is not None and limit < 0:
        raise ValueError("limit must be nonnegative")
    ordered = list(rows)
    for field in reversed(fields):
        present_rows: list[dict[str, object]] = []
        missing_rows: list[dict[str, object]] = []
        for row in ordered:
            if field not in row or row[field] is None:
                if missing == "error":
                    raise KeyError(f"Missing sort value for field: {field}")
                missing_rows.append(row)
            else:
                present_rows.append(row)
        try:
            present_rows.sort(key=lambda row: row[field], reverse=field in descending)
        except TypeError as exc:
            raise TypeError(f"Values for field {field} are not mutually orderable") from exc
        if missing == "first":
            ordered = missing_rows + present_rows
        else:
            ordered = present_rows + missing_rows
    if limit is not None:
        return ordered[:limit]
    return ordered

def select_jobs_within_budget(jobs: list[tuple[str, int, int]], budget: int, *, max_jobs: int | None = None, skip_oversized: bool = True) -> list[str]:
    if budget < 0:
        raise ValueError("budget must be nonnegative")
    if max_jobs is not None and max_jobs < 0:
        raise ValueError("max_jobs must be nonnegative")
    queue: list[tuple[int, int, str, int]] = []
    seen: set[str] = set()
    for position, (job_id, priority, cost) in enumerate(jobs):
        if cost < 0:
            raise ValueError(f"Job cost must be nonnegative: {job_id}")
        if job_id in seen:
            raise ValueError(f"Duplicate job ID: {job_id}")
        seen.add(job_id)
        queue.append((priority, position, job_id, cost))
    heapq.heapify(queue)
    selected: list[str] = []
    remaining = budget
    while queue:
        if max_jobs is not None and len(selected) >= max_jobs:
            break
        priority, position, job_id, cost = heapq.heappop(queue)
        if cost > remaining:
            if skip_oversized:
                continue
            break
        selected.append(job_id)
        remaining -= cost
    return selected

def chunk_items(items: list[object], size: int) -> Iterator[list[object]]:
    if size <= 0:
        raise ValueError("Chunk size must be positive")
    position = 0
    while position < len(items):
        chunk = items[position:position + size]
        yield chunk
        position += size

def sorted_unique_numbers(numbers: Iterable[int]) -> Iterator[int]:
    ordered = sorted(numbers)
    previous = None
    for number in ordered:
        if previous is None or number != previous:
            yield number
            previous = number

def group_records(records: Iterable[dict[str, object]], field: str, minimum_size: int = 1) -> Iterator[tuple[object, list[dict[str, object]]]]:
    if minimum_size < 1:
        raise ValueError("Minimum group size must be positive")
    groups: dict[object, list[dict[str, object]]] = {}
    for record in records:
        if field not in record:
            continue
        value = record[field]
        if value not in groups:
            groups[value] = []
        groups[value].append(record)
    for value, members in groups.items():
        if len(members) < minimum_size:
            continue
        yield value, members

def merge_layer_snapshots(layers: Iterable[dict[str, object]], overwrite: bool = True, delete_none: bool = False) -> Iterator[dict[str, object]]:
    merged: dict[str, object] = {}
    for layer in layers:
        for key, value in layer.items():
            if delete_none and value is None:
                if key in merged:
                    del merged[key]
                continue
            if key in merged and not overwrite:
                continue
            merged[key] = value
        snapshot = merged.copy()
        yield snapshot

def flatten_nested_items(items: Iterable[object], *, max_depth: int | None = None) -> Iterator[object]:
    if max_depth is not None and max_depth < 0:
        raise ValueError("Maximum depth cannot be negative")
    root_id = id(items) if isinstance(items, (list, tuple)) else None
    active: set[int] = set()
    if root_id is not None:
        active.add(root_id)
    stack: list[tuple[Iterator[object], int, int | None]] = [(iter(items), 0, root_id)]
    while stack:
        iterator, depth, container_id = stack[-1]
        try:
            item = next(iterator)
        except StopIteration:
            stack.pop()
            if container_id is not None:
                active.remove(container_id)
            continue
        if not isinstance(item, (list, tuple)):
            yield item
            continue
        if max_depth is not None and depth >= max_depth:
            yield item
            continue
        item_id = id(item)
        if item_id in active:
            raise ValueError("Nested collection contains a cycle")
        active.add(item_id)
        stack.append((iter(item), depth + 1, item_id))

def merge_priority_streams(*streams: Iterable[tuple[int, str]], descending: bool = False, validate_order: bool = True) -> Iterator[tuple[int, str]]:
    heap: list[tuple[int, int, int, str]] = []
    iterators = [iter(stream) for stream in streams]
    last_priorities: dict[int, int] = {}
    for index, iterator in enumerate(iterators):
        try:
            priority, label = next(iterator)
        except StopIteration:
            continue
        last_priorities[index] = priority
        rank = -priority if descending else priority
        heapq.heappush(heap, (rank, index, priority, label))
    while heap:
        rank, index, priority, label = heapq.heappop(heap)
        yield priority, label
        try:
            next_priority, next_label = next(iterators[index])
        except StopIteration:
            continue
        if validate_order:
            previous = last_priorities[index]
            if descending and next_priority > previous:
                raise ValueError("Priority stream is not sorted in descending order")
            if not descending and next_priority < previous:
                raise ValueError("Priority stream is not sorted in ascending order")
        last_priorities[index] = next_priority
        next_rank = -next_priority if descending else next_priority
        heapq.heappush(heap, (next_rank, index, next_priority, next_label))

def group_staff_by_department(self: object, staff: list[dict[str, str]]) -> dict[str, list[dict[str, str]]]:
    departments: dict[str, list[dict[str, str]]] = {}
    for person in staff:
        department = person.get("department", "unassigned")
        if department not in departments:
            departments[department] = []
        departments[department].append(person)
    return departments

def flatten_page_ids(self: object, pages: list[list[str]]) -> list[str]:
    identifiers: list[str] = []
    for page in pages:
        for identifier in page:
            identifiers.append(identifier)
    return identifiers

def chunk_readings(self: object, readings: list[float], size: int = 100) -> list[list[float]]:
    if isinstance(size, bool) or not isinstance(size, int):
        raise TypeError("Chunk size must be an integer")
    if size <= 0:
        raise ValueError("Chunk size must be positive")
    chunks: list[list[float]] = []
    for start in range(0, len(readings), size):
        stop = min(start + size, len(readings))
        chunk = readings[start:stop]
        chunks.append(chunk)
    return chunks

def merge_stock_adjustments(self: object, adjustments: list[dict[str, int]], drop_zero: bool = True) -> dict[str, int]:
    totals: dict[str, int] = {}
    for adjustment in adjustments:
        for sku, change in adjustment.items():
            if isinstance(change, bool) or not isinstance(change, int):
                raise TypeError("Stock adjustments must be integers")
            totals[sku] = totals.get(sku, 0) + change
    if drop_zero:
        zero_skus: list[str] = []
        for sku, total in totals.items():
            if total == 0:
                zero_skus.append(sku)
        for sku in zero_skus:
            del totals[sku]
    return totals

def sort_scored_records(self: object, records: list[dict[str, object]], *, score_key: str = "score", descending: bool = True, missing: str = "last") -> list[dict[str, object]]:
    if missing not in ("first", "last", "reject"):
        raise ValueError("Missing-score policy must be first, last, or reject")
    scored: list[tuple[int | float, dict[str, object]]] = []
    unscored: list[dict[str, object]] = []
    for record in records:
        score = record.get(score_key)
        if score is None:
            if missing == "reject":
                raise ValueError("A record is missing its score")
            unscored.append(record)
            continue
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise TypeError("Scores must be integers or floats")
        if isinstance(score, float) and not math.isfinite(score):
            raise ValueError("Scores must be finite")
        scored.append((score, record))
    scored.sort(key=lambda item: item[0], reverse=descending)
    ordered = [record for score, record in scored]
    if missing == "first":
        return unscored + ordered
    return ordered + unscored

def select_pending_jobs(self: object, jobs: list[dict[str, object]], *, limit: int, priority_key: str = "priority") -> list[dict[str, object]]:
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError("Job limit must be an integer")
    if limit < 0:
        raise ValueError("Job limit cannot be negative")
    if limit == 0:
        return []
    queue: list[tuple[int | float, int, dict[str, object]]] = []
    for position, job in enumerate(jobs):
        status = job.get("status", "pending")
        if status in ("cancelled", "completed", "running"):
            continue
        if status != "pending":
            raise ValueError("Job status is not recognized")
        if priority_key not in job:
            raise KeyError("Pending job is missing its priority")
        priority = job[priority_key]
        if isinstance(priority, bool) or not isinstance(priority, (int, float)):
            raise TypeError("Job priorities must be integers or floats")
        if isinstance(priority, float) and not math.isfinite(priority):
            raise ValueError("Job priorities must be finite")
        heapq.heappush(queue, (priority, position, job))
    selected: list[dict[str, object]] = []
    while queue and len(selected) < limit:
        priority, position, job = heapq.heappop(queue)
        selected.append(job)
    return selected

async def merge_inventory_counts(sources: list[dict[str, int]], minimum: int = 0, pause: float = 0.0) -> dict[str, int]:
    if pause < 0:
        raise ValueError("pause must be nonnegative")
    totals: dict[str, int] = {}
    for source in sources:
        await asyncio.sleep(pause)
        for sku, count in source.items():
            totals[sku] = totals.get(sku, 0) + count
    retained: dict[str, int] = {}
    for sku, count in totals.items():
        if count >= minimum:
            retained[sku] = count
    return retained

async def merge_sorted_streams(streams: list[AsyncIterator[int]], *, limit: int | None = None, verify_order: bool = True) -> list[int]:
    if limit is not None and limit < 0:
        raise ValueError("limit must be nonnegative")
    if limit == 0:
        return []
    heap: list[tuple[int, int]] = []
    previous: dict[int, int] = {}
    results: list[int] = []
    for index, stream in enumerate(streams):
        try:
            value = await anext(stream)
        except StopAsyncIteration:
            continue
        previous[index] = value
        heapq.heappush(heap, (value, index))
    while heap:
        value, index = heapq.heappop(heap)
        results.append(value)
        if limit is not None and len(results) >= limit:
            break
        try:
            following = await anext(streams[index])
        except StopAsyncIteration:
            continue
        if verify_order and following < previous[index]:
            raise ValueError(f"stream {index} is not sorted in ascending order")
        previous[index] = following
        heapq.heappush(heap, (following, index))
    return results

def point_distance(first: tuple[float, float], second: tuple[float, float]) -> float:
    first_x, first_y = first
    second_x, second_y = second
    horizontal = second_x - first_x
    vertical = second_y - first_y
    return math.hypot(horizontal, vertical)

def grid_neighbors(cell: tuple[int, int], shape: tuple[int, int], diagonals: bool = False, wrapping: bool = False) -> list[tuple[int, int]]:
    row, column = cell
    rows, columns = shape
    if rows <= 0 or columns <= 0:
        raise ValueError("Grid dimensions must be positive")
    if not (0 <= row < rows and 0 <= column < columns):
        raise ValueError("The cell must lie inside the grid")
    offsets = [(-1, 0), (0, -1), (0, 1), (1, 0)]
    if diagonals:
        offsets.extend([(-1, -1), (-1, 1), (1, -1), (1, 1)])
    neighbors = []
    for row_offset, column_offset in offsets:
        next_row = row + row_offset
        next_column = column + column_offset
        if wrapping:
            next_row %= rows
            next_column %= columns
        elif not (0 <= next_row < rows and 0 <= next_column < columns):
            continue
        candidate = (next_row, next_column)
        if candidate != cell and candidate not in neighbors:
            neighbors.append(candidate)
    return neighbors

def point_in_polygon(point: tuple[float, float], vertices: list[tuple[float, float]], *, include_boundary: bool = True, tolerance: float = 0.0) -> bool:
    if not math.isfinite(tolerance) or tolerance < 0:
        raise ValueError("Tolerance must be finite and nonnegative")
    if len(vertices) < 3:
        raise ValueError("A polygon requires at least three vertices")
    if not all(math.isfinite(value) for vertex in vertices for value in vertex):
        raise ValueError("Polygon coordinates must be finite")
    x, y = point
    if not math.isfinite(x) or not math.isfinite(y):
        raise ValueError("Point coordinates must be finite")
    inside = False
    previous_x, previous_y = vertices[-1]
    for current_x, current_y in vertices:
        edge_x = current_x - previous_x
        edge_y = current_y - previous_y
        length_squared = edge_x * edge_x + edge_y * edge_y
        if length_squared == 0:
            nearest_x, nearest_y = previous_x, previous_y
        else:
            projection = ((x - previous_x) * edge_x + (y - previous_y) * edge_y) / length_squared
            projection = max(0.0, min(1.0, projection))
            nearest_x = previous_x + projection * edge_x
            nearest_y = previous_y + projection * edge_y
        if math.hypot(x - nearest_x, y - nearest_y) <= tolerance:
            return include_boundary
        if (previous_y > y) != (current_y > y):
            crossing_x = previous_x + (y - previous_y) * edge_x / edge_y
            if x < crossing_x:
                inside = not inside
        previous_x, previous_y = current_x, current_y
    return inside

def clip_segment_to_box(start: tuple[float, float], end: tuple[float, float], box: tuple[float, float, float, float], *, minimum_length: float = 0.0) -> tuple[tuple[float, float], tuple[float, float]] | None:
    if not math.isfinite(minimum_length) or minimum_length < 0:
        raise ValueError("Minimum length must be finite and nonnegative")
    if not all(math.isfinite(value) for value in (*start, *end, *box)):
        raise ValueError("All coordinates must be finite")
    left, bottom, right, top = box
    if left > right or bottom > top:
        raise ValueError("Bounding box limits must be ordered")
    start_x, start_y = start
    delta_x = end[0] - start_x
    delta_y = end[1] - start_y
    lower = 0.0
    upper = 1.0
    constraints = [(-delta_x, start_x - left), (delta_x, right - start_x), (-delta_y, start_y - bottom), (delta_y, top - start_y)]
    for direction, distance in constraints:
        if direction == 0:
            if distance < 0:
                return None
            continue
        ratio = distance / direction
        if direction < 0:
            lower = max(lower, ratio)
        else:
            upper = min(upper, ratio)
        if lower > upper:
            return None
    clipped_start = (start_x + lower * delta_x, start_y + lower * delta_y)
    clipped_end = (start_x + upper * delta_x, start_y + upper * delta_y)
    length = math.hypot(clipped_end[0] - clipped_start[0], clipped_end[1] - clipped_start[1])
    if length < minimum_length:
        return None
    return clipped_start, clipped_end

def distance_to(self: "Point", target: tuple[float, float]) -> float:
    x, y = self.position
    target_x, target_y = target
    dx = target_x - x
    dy = target_y - y
    return math.hypot(dx, dy)

def cell_center(self: "Grid", row: int, column: int, clamp: bool = False) -> tuple[float, float]:
    rows, columns = self.shape
    width, height = self.cell_size
    if rows <= 0 or columns <= 0:
        raise ValueError("Grid dimensions must be positive")
    if not math.isfinite(width) or not math.isfinite(height) or width <= 0 or height <= 0:
        raise ValueError("Cell dimensions must be finite and positive")
    if clamp:
        row = min(max(row, 0), rows - 1)
        column = min(max(column, 0), columns - 1)
    elif not (0 <= row < rows and 0 <= column < columns):
        raise IndexError("Cell index is outside the grid")
    origin_x, origin_y = self.origin
    center_x = origin_x + (column + 0.5) * width
    center_y = origin_y + (row + 0.5) * height
    return center_x, center_y

def clip_segment(self: "BoundingBox", start: tuple[float, float], end: tuple[float, float], *, padding: float = 0.0) -> tuple[tuple[float, float], tuple[float, float]] | None:
    minimum_x, minimum_y, maximum_x, maximum_y = self.bounds
    x0, y0 = start
    x1, y1 = end
    values = (minimum_x, minimum_y, maximum_x, maximum_y, x0, y0, x1, y1, padding)
    if not all(math.isfinite(value) for value in values):
        raise ValueError("Bounds, endpoints, and padding must be finite")
    if minimum_x > maximum_x or minimum_y > maximum_y:
        raise ValueError("Bounding box limits are reversed")
    if padding < 0:
        raise ValueError("Padding must be nonnegative")
    minimum_x -= padding
    minimum_y -= padding
    maximum_x += padding
    maximum_y += padding
    dx, dy = x1 - x0, y1 - y0
    if not all(math.isfinite(value) for value in (minimum_x, minimum_y, maximum_x, maximum_y, dx, dy)):
        raise ValueError("Geometry exceeds the supported numeric range")
    entering, leaving = 0.0, 1.0
    constraints = ((-dx, x0 - minimum_x), (dx, maximum_x - x0), (-dy, y0 - minimum_y), (dy, maximum_y - y0))
    for direction, distance in constraints:
        if direction == 0:
            if distance < 0:
                return None
            continue
        ratio = distance / direction
        if direction < 0:
            entering = max(entering, ratio)
        else:
            leaving = min(leaving, ratio)
        if entering > leaving:
            return None
    clipped_start = (x0 + entering * dx, y0 + entering * dy)
    clipped_end = (x0 + leaving * dx, y0 + leaving * dy)
    return clipped_start, clipped_end

def classify_point(self: "Polygon", point: tuple[float, float], *, tolerance: float = 1e-9) -> str:
    if not math.isfinite(tolerance) or tolerance < 0:
        raise ValueError("Tolerance must be finite and nonnegative")
    vertices = self.vertices
    if len(vertices) < 3:
        raise ValueError("A polygon requires at least three vertices")
    x, y = point
    if not math.isfinite(x) or not math.isfinite(y):
        raise ValueError("Point coordinates must be finite")
    if any(not math.isfinite(value) for vertex in vertices for value in vertex):
        raise ValueError("Polygon coordinates must be finite")
    inside = False
    previous_x, previous_y = vertices[-1]
    for current_x, current_y in vertices:
        dx = current_x - previous_x
        dy = current_y - previous_y
        edge_length = math.hypot(dx, dy)
        if not math.isfinite(edge_length):
            raise ValueError("Polygon edge exceeds the supported numeric range")
        if edge_length == 0:
            distance = math.hypot(x - previous_x, y - previous_y)
        else:
            unit_x, unit_y = dx / edge_length, dy / edge_length
            projection = (x - previous_x) * unit_x + (y - previous_y) * unit_y
            projection = min(max(projection, 0.0), edge_length)
            nearest_x = previous_x + projection * unit_x
            nearest_y = previous_y + projection * unit_y
            distance = math.hypot(x - nearest_x, y - nearest_y)
        if distance <= tolerance:
            return "boundary"
        if (previous_y > y) != (current_y > y):
            fraction = (y - previous_y) / dy
            crossing_x = previous_x + fraction * dx
            if x < crossing_x:
                inside = not inside
        previous_x, previous_y = current_x, current_y
    return "inside" if inside else "outside"

def grid_cell_centers(rows: int, columns: int) -> Iterator[tuple[float, float]]:
    for row in range(rows):
        y = row + 0.5
        for column in range(columns):
            x = column + 0.5
            yield x, y

def polygon_edges(vertices: list[tuple[float, float]], closed: bool = True) -> Iterator[tuple[tuple[float, float], tuple[float, float]]]:
    count = len(vertices)
    if count < 2:
        return
    for index in range(count - 1):
        yield vertices[index], vertices[index + 1]
    if closed:
        yield vertices[-1], vertices[0]

def sample_segment(start: tuple[float, float], end: tuple[float, float], divisions: int = 10, include_end: bool = True) -> Iterator[tuple[float, float]]:
    if not isinstance(divisions, int) or isinstance(divisions, bool):
        raise TypeError("divisions must be an integer")
    if divisions < 1:
        raise ValueError("divisions must be positive")
    x0, y0 = start
    x1, y1 = end
    if not all(math.isfinite(value) for value in (x0, y0, x1, y1)):
        raise ValueError("segment coordinates must be finite")
    for index in range(divisions):
        fraction = index / divisions
        x = (1.0 - fraction) * x0 + fraction * x1
        y = (1.0 - fraction) * y0 + fraction * y1
        yield x, y
    if include_end:
        yield x1, y1

def points_in_annulus(points: Iterable[tuple[float, float]], center: tuple[float, float], minimum: float = 0.0, maximum: float = math.inf) -> Iterator[tuple[tuple[float, float], float]]:
    if not math.isfinite(minimum) or minimum < 0:
        raise ValueError("minimum distance must be finite and nonnegative")
    if math.isnan(maximum) or maximum < minimum:
        raise ValueError("maximum distance must be at least the minimum")
    cx, cy = center
    if not math.isfinite(cx) or not math.isfinite(cy):
        raise ValueError("center coordinates must be finite")
    for x, y in points:
        if not math.isfinite(x) or not math.isfinite(y):
            raise ValueError("point coordinates must be finite")
        distance = math.hypot(x - cx, y - cy)
        if minimum <= distance <= maximum:
            yield (x, y), distance

def clip_convex_polygon(vertices: Iterable[tuple[float, float]], *, bounds: tuple[float, float, float, float], closed: bool = False) -> Iterator[tuple[float, float]]:
    xmin, ymin, xmax, ymax = bounds
    if not all(math.isfinite(value) for value in bounds):
        raise ValueError("bounding box coordinates must be finite")
    if xmin > xmax or ymin > ymax:
        raise ValueError("bounding box limits are reversed")
    polygon = list(vertices)
    if any(not math.isfinite(x) or not math.isfinite(y) for x, y in polygon):
        raise ValueError("polygon coordinates must be finite")
    if len(polygon) > 1 and polygon[0] == polygon[-1]:
        polygon.pop()
    for a, b, limit in ((1, 0, xmin), (-1, 0, -xmax), (0, 1, ymin), (0, -1, -ymax)):
        if not polygon:
            return
        output = []
        previous = polygon[-1]
        previous_distance = a * previous[0] + b * previous[1] - limit
        for current in polygon:
            current_distance = a * current[0] + b * current[1] - limit
            if (previous_distance >= 0) != (current_distance >= 0):
                fraction = previous_distance / (previous_distance - current_distance)
                intersection = ((1 - fraction) * previous[0] + fraction * current[0], (1 - fraction) * previous[1] + fraction * current[1])
                output.append(intersection)
            if current_distance >= 0:
                output.append(current)
            previous = current
            previous_distance = current_distance
        polygon = []
        for point in output:
            if not polygon or point != polygon[-1]:
                polygon.append(point)
        if len(polygon) > 1 and polygon[0] == polygon[-1]:
            polygon.pop()
    for point in polygon:
        yield point
    if closed and polygon:
        yield polygon[0]

async def nearest_available_grid_cell(point: tuple[float, float], occupied: set[tuple[int, int]], *, spacing: float = 1.0, radius: int = 8) -> tuple[int, int]:
    if not math.isfinite(spacing) or spacing <= 0:
        raise ValueError("Grid spacing must be finite and positive")
    if not isinstance(radius, int):
        raise TypeError("Search radius must be an integer")
    if radius < 0:
        raise ValueError("Search radius must be nonnegative")
    x, y = point
    if not math.isfinite(x) or not math.isfinite(y):
        raise ValueError("Point coordinates must be finite")
    grid_x, grid_y = x / spacing, y / spacing
    if not math.isfinite(grid_x) or not math.isfinite(grid_y):
        raise ValueError("Scaled coordinates exceed the supported numeric range")
    center_x, center_y = round(grid_x), round(grid_y)
    best_cell: tuple[int, int] | None = None
    best_key: tuple[float, int, int] | None = None
    for column in range(center_x - radius, center_x + radius + 1):
        await asyncio.sleep(0)
        for row in range(center_y - radius, center_y + radius + 1):
            cell = (column, row)
            if cell in occupied:
                continue
            distance = math.hypot(column - grid_x, row - grid_y)
            key = (distance, column, row)
            if best_key is None or key < best_key:
                best_key = key
                best_cell = cell
    if best_cell is None:
        raise ValueError("No available grid cell exists within the search radius")
    return best_cell

def cached_utf8_size(text: str, cache: dict[str, int]) -> int:
    if text not in cache:
        encoded = text.encode("utf-8")
        size = len(encoded)
        cache[text] = size
    return cache[text]

def get_unexpired_value(cache: dict[str, tuple[float, object]], key: str, now: float | None = None) -> object | None:
    if now is None:
        now = time.monotonic()
    if not math.isfinite(now):
        raise ValueError("Current time must be finite")
    if key not in cache:
        return None
    expires_at, value = cache[key]
    if expires_at <= now:
        del cache[key]
        return None
    return value

def store_lru_value(cache: dict[str, object], key: str, value: object, capacity: int = 128) -> list[str]:
    if capacity < 0:
        raise ValueError("Cache capacity cannot be negative")
    evicted = []
    if key in cache:
        del cache[key]
    cache[key] = value
    while len(cache) > capacity:
        oldest_key = next(iter(cache))
        del cache[oldest_key]
        evicted.append(oldest_key)
    return evicted

def memoize_call(cache: dict[tuple[object, ...], tuple[float, object]], function: Callable[..., object], *args: object, ttl: float = 60.0, max_entries: int = 128, **kwargs: object) -> object:
    if not math.isfinite(ttl) or ttl < 0:
        raise ValueError("TTL must be finite and nonnegative")
    if max_entries < 1:
        raise ValueError("Maximum cache entries must be positive")
    if ttl == 0:
        return function(*args, **kwargs)
    key = (function, args, tuple(sorted(kwargs.items())))
    try:
        hash(key)
    except TypeError as exc:
        raise TypeError("The callable and its arguments must be hashable") from exc
    now = time.monotonic()
    if key in cache:
        expires_at, value = cache[key]
        if expires_at > now:
            del cache[key]
            cache[key] = (expires_at, value)
            return value
        del cache[key]
    value = function(*args, **kwargs)
    completed_at = time.monotonic()
    expires_at = completed_at + ttl
    if not math.isfinite(expires_at):
        raise ValueError("Computed expiration time must be finite")
    expired_keys = [stored_key for stored_key, entry in cache.items() if entry[0] <= completed_at]
    for expired_key in expired_keys:
        del cache[expired_key]
    cache.pop(key, None)
    cache[key] = (expires_at, value)
    while len(cache) > max_entries:
        oldest_key = next(iter(cache))
        del cache[oldest_key]
    return value

def prune_expired_entries(cache: dict[str, tuple[float, object]], counters: dict[str, int], *, now: float | None = None, scan_limit: int | None = None) -> list[str]:
    if scan_limit is not None and scan_limit < 0:
        raise ValueError("Scan limit cannot be negative")
    if now is None:
        now = time.monotonic()
    if not math.isfinite(now):
        raise ValueError("Current time must be finite")
    for name in ("expiry_scans", "expiry_evictions"):
        count = counters.get(name, 0)
        if not isinstance(count, int):
            raise TypeError(f"Counter {name} must be an integer")
        if count < 0:
            raise ValueError(f"Counter {name} cannot be negative")
    expired_keys = []
    scanned = 0
    for key, entry in cache.items():
        if scan_limit is not None and scanned >= scan_limit:
            break
        scanned += 1
        expires_at, value = entry
        if expires_at <= now:
            expired_keys.append(key)
    for key in expired_keys:
        del cache[key]
    counters["expiry_scans"] = counters.get("expiry_scans", 0) + scanned
    counters["expiry_evictions"] = counters.get("expiry_evictions", 0) + len(expired_keys)
    return expired_keys

def read_cached(self: object, key: str) -> object:
    if key in self._cache:
        self._hits += 1
        return self._cache[key]
    self._misses += 1
    raise KeyError(f"Cache key not found: {key!r}")

def invalidate_key(self: object, key: str) -> bool:
    if key not in self._cache:
        return False
    del self._cache[key]
    self._invalidations += 1
    return True

def store_with_expiry(self: object, key: str, value: object, ttl: float = 60.0) -> None:
    if not math.isfinite(ttl) or ttl < 0:
        raise ValueError("TTL must be finite and nonnegative")
    if ttl == 0:
        if key in self._entries:
            del self._entries[key]
            self._invalidations += 1
        return
    expires_at = time.monotonic() + ttl
    replacing = key in self._entries
    self._entries[key] = (value, expires_at)
    self._writes += 1
    if replacing:
        self._replacements += 1

def resize_lru(self: object, capacity: int = 128, protected_key: str | None = None) -> list[str]:
    if isinstance(capacity, bool) or not isinstance(capacity, int):
        raise TypeError("Capacity must be an integer")
    if capacity < 0:
        raise ValueError("Capacity cannot be negative")
    if capacity == 0 and protected_key in self._lru:
        raise ValueError("A protected entry requires positive capacity")
    excess = max(0, len(self._lru) - capacity)
    victims = []
    for key in self._lru:
        if len(victims) == excess:
            break
        if key != protected_key:
            victims.append(key)
    for key in victims:
        del self._lru[key]
    self._capacity = capacity
    self._evictions += len(victims)
    return victims

def make_memo_key(self: object, namespace: str, *args: object, **kwargs: object) -> str:
    if not isinstance(namespace, str):
        raise TypeError("Cache namespace must be a string")
    if not namespace:
        raise ValueError("Cache namespace cannot be empty")
    arguments = [("arg", str(index), value) for index, value in enumerate(args)]
    arguments.extend(("kw", name, value) for name, value in sorted(kwargs.items()))
    encoded = []
    for kind, name, value in arguments:
        if value is None:
            tag, payload = "none", ""
        elif type(value) is bool:
            tag, payload = "bool", "1" if value else "0"
        elif type(value) is int:
            tag, payload = "int", str(value)
        elif type(value) is float:
            if not math.isfinite(value):
                raise ValueError("Floating-point cache arguments must be finite")
            tag, payload = "float", value.hex()
        elif type(value) is str:
            tag, payload = "str", value
        elif type(value) is bytes:
            tag, payload = "bytes", value.hex()
        else:
            raise TypeError(f"Unsupported cache argument type: {type(value).__name__}")
        encoded.append([kind, name, tag, payload])
    document = json.dumps([namespace, encoded], ensure_ascii=True, separators=(",", ":"))
    digest = hashlib.sha256(document.encode("ascii")).hexdigest()
    return f"memo:{digest}"

def invalidate_cache_keys(cache: dict[str, object], keys: Iterable[str]) -> Iterator[tuple[str, object]]:
    for key in keys:
        if key not in cache:
            continue
        value = cache.pop(key)
        yield key, value

def memoized_squares(numbers: Iterable[int], cache: dict[int, int]) -> Iterator[int]:
    for number in numbers:
        if number not in cache:
            result = number * number
            cache[number] = result
        yield cache[number]

def purge_expired_entries(cache: dict[str, tuple[object, float | None]], now: float | None = None, limit: int | None = None) -> Iterator[tuple[str, object]]:
    if limit is not None and limit < 0:
        raise ValueError("Purge limit must be nonnegative")
    cutoff = time.time() if now is None else now
    removed = 0
    for key in list(cache):
        if limit is not None and removed >= limit:
            break
        if key not in cache:
            continue
        value, expires_at = cache[key]
        if expires_at is None or expires_at > cutoff:
            continue
        del cache[key]
        removed += 1
        yield key, value

def cache_counter_deltas(snapshots: Iterable[Mapping[str, int]], baseline: Mapping[str, int] | None = None) -> Iterator[dict[str, int]]:
    previous = dict(baseline) if baseline is not None else {}
    if any(value < 0 for value in previous.values()):
        raise ValueError("Baseline counters must be nonnegative")
    for snapshot in snapshots:
        current = dict(snapshot)
        deltas = {}
        for name, value in current.items():
            if value < 0:
                raise ValueError("Cache counters must be nonnegative")
            old_value = previous.get(name, 0)
            if value < old_value:
                deltas[name] = value
            else:
                deltas[name] = value - old_value
        previous = current
        yield deltas

def stream_lru_results(inputs: Iterable[Hashable], compute: Callable[[Hashable], object], cache: OrderedDict[Hashable, object], *, max_entries: int = 128, counters: dict[str, int] | None = None) -> Iterator[tuple[Hashable, object, bool]]:
    if max_entries < 1:
        raise ValueError("LRU capacity must be at least one")
    if counters is None:
        counters = {}
    for key in inputs:
        counters["requests"] = counters.get("requests", 0) + 1
        if key in cache:
            value = cache[key]
            cache.move_to_end(key)
            counters["hits"] = counters.get("hits", 0) + 1
            was_cached = True
        else:
            counters["misses"] = counters.get("misses", 0) + 1
            value = compute(key)
            cache[key] = value
            cache.move_to_end(key)
            was_cached = False
        while len(cache) > max_entries:
            cache.popitem(last=False)
            counters["evictions"] = counters.get("evictions", 0) + 1
        yield key, value, was_cached

def canonical_call_keys(calls: Iterable[tuple[str, tuple[object, ...], dict[str, object]]], *, namespace: str, version: int = 1) -> Iterator[str]:
    if not isinstance(namespace, str) or not namespace:
        raise ValueError("Cache namespace must be a nonempty string")
    if not isinstance(version, int) or isinstance(version, bool) or version < 1:
        raise ValueError("Cache key version must be a positive integer")
    for name, arguments, keywords in calls:
        if not isinstance(name, str) or not name:
            raise ValueError("Call name must be a nonempty string")
        if any(not isinstance(key, str) for key in keywords):
            raise TypeError("Keyword argument names must be strings")
        payload = {
            "namespace": namespace,
            "version": version,
            "call": name,
            "arguments": arguments,
            "keywords": keywords,
        }
        try:
            encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=True, allow_nan=False)
        except (TypeError, ValueError) as error:
            raise ValueError("Call arguments must support canonical JSON encoding") from error
        digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
        yield f"{namespace}:{version}:{digest}"

async def remove_expired_entries(cache: dict[str, tuple[float, str]], now: float) -> int:
    await asyncio.sleep(0)
    expired = [key for key, entry in cache.items() if entry[0] <= now]
    for key in expired:
        del cache[key]
    return len(expired)

async def fetch_with_singleflight(key: str, cache: dict[str, tuple[float, str]], in_flight: dict[str, asyncio.Task[str]], *, loader: Callable[[str], Awaitable[str]], ttl: float = 60.0) -> str:
    if not math.isfinite(ttl) or ttl <= 0:
        raise ValueError("TTL must be finite and positive")
    now = time.monotonic()
    entry = cache.get(key)
    if entry is not None:
        expires_at, value = entry
        if expires_at > now:
            await asyncio.sleep(0)
            return value
        del cache[key]
    task = in_flight.get(key)
    if task is not None and task.done():
        if task.cancelled():
            del in_flight[key]
            task = None
        elif task.exception() is not None:
            del in_flight[key]
            task = None
    if task is None:
        task = asyncio.create_task(loader(key))
        in_flight[key] = task
    try:
        value = await asyncio.shield(task)
        cache[key] = (time.monotonic() + ttl, value)
        return value
    finally:
        if task.done() and in_flight.get(key) is task:
            del in_flight[key]

def roll_dice(count: int, sides: int) -> list[int]:
    if count < 0:
        raise ValueError("Dice count must be nonnegative")
    if sides < 1:
        raise ValueError("Dice must have at least one side")
    rolls = [random.randint(1, sides) for _ in range(count)]
    return rolls

def deal_from_top(deck: list[str], hand_size: int) -> tuple[list[str], list[str]]:
    if not 0 <= hand_size <= len(deck):
        raise ValueError("Hand size must be between zero and the deck size")
    hand = deck[:hand_size]
    remaining = deck[hand_size:]
    return hand, remaining

def schedule_service(arrivals: list[float], service_times: list[float], servers: int = 1) -> list[tuple[int, float, float]]:
    if servers < 1:
        raise ValueError("At least one server is required")
    if len(arrivals) != len(service_times):
        raise ValueError("Each arrival must have a service time")
    if any(not math.isfinite(t) or t < 0 for t in arrivals):
        raise ValueError("Arrival times must be finite and nonnegative")
    if any(not math.isfinite(t) or t < 0 for t in service_times):
        raise ValueError("Service times must be finite and nonnegative")
    if any(current < previous for previous, current in zip(arrivals, arrivals[1:])):
        raise ValueError("Arrival times must be in chronological order")
    available = [(0.0, server) for server in range(servers)]
    heapq.heapify(available)
    schedule = []
    for arrival, duration in zip(arrivals, service_times):
        free_at, server = heapq.heappop(available)
        start = max(arrival, free_at)
        finish = start + duration
        if not math.isfinite(finish):
            raise ValueError("Service completion time exceeds the finite range")
        schedule.append((server, start, finish))
        heapq.heappush(available, (finish, server))
    return schedule

def walk_until_boundary(steps: int, start: int = 0, bounds: tuple[int, int] | None = None) -> list[int]:
    if steps < 0:
        raise ValueError("Step count must be nonnegative")
    if bounds is not None:
        lower, upper = bounds
        if lower >= upper:
            raise ValueError("The lower boundary must be below the upper boundary")
        if not lower <= start <= upper:
            raise ValueError("Starting position must lie within the boundaries")
    position = start
    path = [position]
    for _ in range(steps):
        if bounds is not None and position in bounds:
            break
        position += random.choice((-1, 1))
        path.append(position)
    return path

def simulate_replenishment(initial_stock: int, daily_demand: list[int], *, reorder_point: int, order_quantity: int, lead_days: int = 1) -> tuple[list[int], int, int]:
    if initial_stock < 0 or reorder_point < 0:
        raise ValueError("Initial stock and reorder point must be nonnegative")
    if order_quantity <= 0:
        raise ValueError("Order quantity must be positive")
    if lead_days < 1:
        raise ValueError("Delivery lead time must be at least one day")
    if any(demand < 0 for demand in daily_demand):
        raise ValueError("Daily demand must be nonnegative")
    stock = initial_stock
    pending = {}
    closing_stock = []
    lost_sales = 0
    for day, demand in enumerate(daily_demand):
        if day in pending:
            stock += pending.pop(day)
        if demand <= stock:
            stock -= demand
        else:
            lost_sales += demand - stock
            stock = 0
        inventory_position = stock + sum(pending.values())
        if inventory_position <= reorder_point:
            quantities_needed = (reorder_point - inventory_position) // order_quantity + 1
            delivery_day = day + lead_days
            pending[delivery_day] = pending.get(delivery_day, 0) + quantities_needed * order_quantity
        closing_stock.append(stock)
    outstanding_units = sum(pending.values())
    return closing_stock, lost_sales, outstanding_units

def simulate_arena(initial_health: list[int], *, damage_range: tuple[int, int] = (1, 6), healing: int = 0, max_turns: int = 100) -> tuple[int | None, list[int], int]:
    if len(initial_health) < 2:
        raise ValueError("The arena requires at least two players")
    if any(health <= 0 for health in initial_health):
        raise ValueError("Every player must start with positive health")
    minimum, maximum = damage_range
    if minimum < 1 or maximum < minimum:
        raise ValueError("Damage range must be positive and ordered")
    if healing < 0 or max_turns < 0:
        raise ValueError("Healing and turn limit must be nonnegative")
    health = initial_health.copy()
    active = list(range(len(health)))
    cursor = 0
    turns = 0
    while len(active) > 1 and turns < max_turns:
        attacker = active[cursor]
        targets = [player for player in active if player != attacker]
        target = random.choice(targets)
        damage = random.randint(minimum, maximum)
        health[target] = max(0, health[target] - damage)
        if healing:
            health[attacker] = min(initial_health[attacker], health[attacker] + healing)
        if health[target] == 0:
            active.remove(target)
        turns += 1
        if len(active) > 1:
            cursor = (active.index(attacker) + 1) % len(active)
    if len(active) == 1:
        winner = active[0]
    else:
        winner = None
    return winner, health, turns

def deal_shuffled_hands(cards: list[str], hand_size: int) -> Iterator[list[str]]:
    if hand_size < 1:
        raise ValueError("Hand size must be positive")
    deck = list(cards)
    random.shuffle(deck)
    for offset in range(0, len(deck), hand_size):
        hand = deck[offset:offset + hand_size]
        yield hand

def simulate_service_queue(arrivals: Iterable[tuple[float, float]], opening_time: float = 0.0) -> Iterator[tuple[float, float, float]]:
    if not math.isfinite(opening_time):
        raise ValueError("Opening time must be finite")
    available_at = opening_time
    previous_arrival = -math.inf
    for arrival, duration in arrivals:
        if not math.isfinite(arrival) or not math.isfinite(duration):
            raise ValueError("Arrival times and service durations must be finite")
        if duration < 0:
            raise ValueError("Service duration must be nonnegative")
        if arrival < previous_arrival:
            raise ValueError("Arrivals must be in chronological order")
        start = max(arrival, available_at)
        finish = start + duration
        if not math.isfinite(finish):
            raise ValueError("Service completion time overflowed")
        waiting = start - arrival
        previous_arrival = arrival
        available_at = finish
        yield start, finish, waiting

def walk_on_grid(steps: int, start: tuple[int, int] = (0, 0), bounds: tuple[int, int, int, int] | None = None) -> Iterator[tuple[int, int]]:
    if steps < 0:
        raise ValueError("Step count must be nonnegative")
    x, y = start
    if bounds is not None:
        left, bottom, right, top = bounds
        if left > right or bottom > top:
            raise ValueError("Grid bounds must not be reversed")
        if not (left <= x <= right and bottom <= y <= top):
            raise ValueError("Starting position must be inside the grid")
    yield x, y
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))
    for _ in range(steps):
        dx, dy = random.choice(directions)
        next_x, next_y = x + dx, y + dy
        if bounds is None:
            x, y = next_x, next_y
        elif left <= next_x <= right and bottom <= next_y <= top:
            x, y = next_x, next_y
        yield x, y

def apply_inventory_events(events: Iterable[tuple[str, int]], *, initial: dict[str, int] | None = None, allow_backorders: bool = False, strict_skus: bool = False) -> Iterator[tuple[str, int, int]]:
    stock = dict(initial) if initial is not None else {}
    for sku, quantity in stock.items():
        if not isinstance(sku, str) or not sku:
            raise ValueError("Initial inventory keys must be nonempty strings")
        if not isinstance(quantity, int) or isinstance(quantity, bool):
            raise TypeError("Initial quantities must be integers")
        if quantity < 0 and not allow_backorders:
            raise ValueError("Initial inventory cannot contain backorders")
    for sku, change in events:
        if not isinstance(sku, str) or not sku:
            raise ValueError("Event SKU must be a nonempty string")
        if not isinstance(change, int) or isinstance(change, bool):
            raise TypeError("Inventory changes must be integers")
        if sku not in stock:
            if strict_skus:
                raise KeyError(f"Unknown inventory SKU: {sku}")
            before = 0
        else:
            before = stock[sku]
        after = before + change
        if after < 0 and not allow_backorders:
            raise ValueError(f"Insufficient inventory for SKU: {sku}")
        stock[sku] = after
        yield sku, before, after

def simulate_dice_race(players: list[str], *, winning_score: int = 20, max_turns: int = 100, seed: int | None = None) -> Iterator[tuple[int, str, int, int, str]]:
    if not players:
        raise ValueError("At least one player is required")
    if any(not isinstance(player, str) or not player for player in players):
        raise ValueError("Player names must be nonempty strings")
    if len(set(players)) != len(players):
        raise ValueError("Player names must be unique")
    if winning_score < 1 or max_turns < 1:
        raise ValueError("Winning score and turn limit must be positive")
    roster = tuple(players)
    scores = dict.fromkeys(roster, 0)
    rng = random.Random(seed)
    for turn in range(1, max_turns + 1):
        player = roster[(turn - 1) % len(roster)]
        roll = rng.randint(1, 6)
        if roll == 1:
            scores[player] = max(0, scores[player] - 2)
            status = "penalty"
        else:
            scores[player] += roll
            status = "advance"
        if scores[player] >= winning_score:
            status = "win"
        elif turn == max_turns:
            status = "turn_limit"
        yield turn, player, roll, scores[player], status
        if status == "win":
            return

def draw_cards(self: "CardGame", count: int) -> list[str]:
    if count < 0:
        raise ValueError("The card count cannot be negative")
    if count > len(self.deck):
        raise ValueError("There are not enough cards in the deck")
    drawn = []
    for _ in range(count):
        drawn.append(self.deck.pop())
    self.hand.extend(drawn)
    return drawn

def walk_line(self: "RandomWalker", steps: int, boundary: int | None = None) -> list[int]:
    if steps < 0:
        raise ValueError("The step count cannot be negative")
    if boundary is not None and boundary < 0:
        raise ValueError("The boundary cannot be negative")
    if boundary is not None and abs(self.position) > boundary:
        raise ValueError("The starting position is outside the boundary")
    visited = [self.position]
    for _ in range(steps):
        direction = self.rng.choice((-1, 1))
        candidate = self.position + direction
        if boundary == 0:
            candidate = 0
        elif boundary is not None and abs(candidate) > boundary:
            candidate = self.position - direction
        self.position = candidate
        self.path.append(candidate)
        visited.append(candidate)
    self.steps_taken += steps
    return visited

def settle_inventory_day(self: "InventorySimulator", demand: dict[str, int], *, arrivals: dict[str, int] | None = None, carry_unfilled: bool = True) -> dict[str, dict[str, int]]:
    incoming = {} if arrivals is None else dict(arrivals)
    requested = dict(demand)
    stock = dict(self.stock)
    backlog = dict(self.backorders)
    for quantities in (incoming, requested, stock, backlog):
        for product, quantity in quantities.items():
            if not isinstance(product, str) or not product:
                raise ValueError("Product names must be nonempty strings")
            if type(quantity) is not int:
                raise TypeError("Inventory quantities must be integers")
            if quantity < 0:
                raise ValueError("Inventory quantities cannot be negative")
    for product, quantity in incoming.items():
        stock[product] = stock.get(product, 0) + quantity
    fulfilled = {}
    unmet = {}
    products = sorted(set(requested) | set(backlog))
    for product in products:
        needed = requested.get(product, 0) + backlog.get(product, 0)
        available = stock.get(product, 0)
        supplied = min(needed, available)
        if supplied:
            fulfilled[product] = supplied
        stock[product] = available - supplied
        if supplied < needed:
            unmet[product] = needed - supplied
    self.stock = stock
    self.backorders = dict(unmet) if carry_unfilled else {}
    self.day += 1
    return {"fulfilled": fulfilled, "unmet": unmet}

def resolve_combat_turn(self: "CombatGame", actor: str, action: str, *, target: str | None = None) -> dict[str, str | int | None]:
    if not self.turn_order:
        raise ValueError("The game has no players")
    if actor != self.turn_order[self.turn_index]:
        raise ValueError("It is not this player's turn")
    player = self.players[actor]
    if player["health"] <= 0:
        raise ValueError("A defeated player cannot act")
    if action not in ("attack", "heal", "guard"):
        raise ValueError("Unknown combat action")
    if action == "guard" and target is not None:
        raise ValueError("Guarding does not accept a target")
    if action != "guard" and (target not in self.players or self.players[target]["health"] <= 0):
        raise ValueError("The target must be a living player")
    cost = {"attack": 2, "heal": 3, "guard": 0}[action]
    if player["energy"] < cost:
        raise ValueError("The player has insufficient energy")
    player["energy"] -= cost
    amount = 0
    if action == "attack":
        victim = self.players[target]
        damage = max(0, self.rng.randint(2, 6) - victim["shield"])
        amount = min(damage, victim["health"])
        victim["health"] -= amount
        victim["shield"] = 0
    elif action == "heal":
        recipient = self.players[target]
        amount = min(4, recipient["max_health"] - recipient["health"])
        recipient["health"] += amount
    else:
        player["shield"] = 3
        player["energy"] = min(player["max_energy"], player["energy"] + 2)
    for offset in range(1, len(self.turn_order) + 1):
        next_index = (self.turn_index + offset) % len(self.turn_order)
        if self.players[self.turn_order[next_index]]["health"] > 0:
            self.turn_index = next_index
            break
    return {"actor": actor, "action": action, "target": target, "amount": amount, "next": self.turn_order[self.turn_index]}

async def draw_random_card(deck: list[str], delay: float = 0.0) -> str:
    if delay < 0:
        raise ValueError("Draw delay cannot be negative")
    await asyncio.sleep(delay)
    if not deck:
        raise ValueError("Cannot draw from an empty deck")
    return deck.pop(random.randrange(len(deck)))

async def walk_with_reflecting_boundaries(steps: int, bounds: tuple[int, int], start: int = 0, delay: float = 0.0) -> list[int]:
    lower, upper = bounds
    if lower >= upper:
        raise ValueError("The lower boundary must be below the upper boundary")
    if steps < 0 or delay < 0:
        raise ValueError("Steps and delay must be nonnegative")
    if not lower <= start <= upper:
        raise ValueError("Starting position must lie within the boundaries")
    position = start
    path = [position]
    for _ in range(steps):
        await asyncio.sleep(delay)
        candidate = position + random.choice((-1, 1))
        if candidate < lower:
            candidate = lower + 1
        elif candidate > upper:
            candidate = upper - 1
        position = candidate
        path.append(position)
    return path

async def fulfill_inventory_orders(initial_stock: dict[str, int], orders: list[tuple[str, int]], *, shortage_policy: str = "reject", delay: float = 0.0) -> tuple[dict[str, int], list[tuple[str, int, str]]]:
    if shortage_policy not in {"reject", "partial", "raise"}:
        raise ValueError("Shortage policy must be reject, partial, or raise")
    if delay < 0:
        raise ValueError("Order delay cannot be negative")
    if any(quantity < 0 for quantity in initial_stock.values()):
        raise ValueError("Initial stock quantities cannot be negative")
    if any(quantity <= 0 for _, quantity in orders):
        raise ValueError("Order quantities must be positive")
    stock = initial_stock.copy()
    outcomes: list[tuple[str, int, str]] = []
    for sku, requested in orders:
        await asyncio.sleep(delay)
        available = stock.get(sku, 0)
        if available >= requested:
            fulfilled = requested
            status = "fulfilled"
        elif shortage_policy == "raise":
            raise ValueError(f"Insufficient stock for {sku}: requested {requested}, available {available}")
        elif shortage_policy == "partial" and available > 0:
            fulfilled = available
            status = "partial"
        else:
            fulfilled = 0
            status = "rejected"
        if fulfilled:
            stock[sku] = available - fulfilled
        outcomes.append((sku, fulfilled, status))
    return stock, outcomes

async def simulate_arena_battle(players: dict[str, int], *, damage_range: tuple[int, int] = (1, 6), max_rounds: int = 100, turn_delay: float = 0.0) -> tuple[str | None, dict[str, int], int]:
    if len(players) < 2:
        raise ValueError("An arena battle requires at least two players")
    if any(health <= 0 for health in players.values()):
        raise ValueError("All players must start with positive health")
    minimum_damage, maximum_damage = damage_range
    if minimum_damage < 1 or maximum_damage < minimum_damage:
        raise ValueError("Damage bounds must be positive and ordered")
    if max_rounds < 1 or turn_delay < 0:
        raise ValueError("Round limit must be positive and turn delay nonnegative")
    health = players.copy()
    for round_number in range(1, max_rounds + 1):
        turn_order = [name for name, remaining in health.items() if remaining > 0]
        random.shuffle(turn_order)
        for attacker in turn_order:
            if health[attacker] <= 0:
                continue
            targets = [name for name, remaining in health.items() if name != attacker and remaining > 0]
            if not targets:
                return attacker, health, round_number
            await asyncio.sleep(turn_delay)
            target = random.choice(targets)
            damage = random.randint(minimum_damage, maximum_damage)
            health[target] = max(0, health[target] - damage)
            if health[target] == 0:
                survivors = [name for name, remaining in health.items() if remaining > 0]
                if len(survivors) == 1:
                    return survivors[0], health, round_number
    return None, health, max_rounds
